programs.sol:
"""Approximate a multilingual possessive-relative spelling detector.

The largest responses are on 'whose' and counterparts such as cuyo, deren,
article + cui, dont + article, and Russian чьи. Token splits and case affect
strength. Recent French function words distinguish dont from English 'dont'.
Smaller rules cover relative markers, possessive pronouns, 'the only/very',
'the kind/type of', and negated 'even'. Repeated double-middle-dot tokens
receive a negative value. Unmatched tokens receive 0.003, ignoring irregular
lexical responses and most small activation variation.
"""
import re

READS = ()

# Relative markers in Indonesian, Arabic and Danish.
RELATIVES = {
    'yang': 1.05,
    'التي': 1.07,
    'الذي': 0.89,
    'الذين': 0.88,
    'hvis': 2.7,
}
FRENCH_CUES = re.compile(
    r'\b(la|le|les|des|du|une|un|et|pour|dans|sur|est|sont|avec|aux|vous|nous)\b'
    r'|[éèàçùêôîûœ]'
)


def response(token, previous, tail):
    word = token.strip().lower()
    prev = previous.strip().lower()
    if word == 'whose':
        return 7.9 if token[:1].isspace() else 6.9
    if token == 'ose' and prev == 'wh':
        return 14.4 if previous.strip() == 'Wh' else 11.5
    if token == 'SE' and previous.strip() == 'WHO':
        return 16.0
    if token in ("'s", '’s') and prev == 'who':
        return 1.8
    if word == 'deren':
        if not tail:
            return 2.0
        if prev == 'und':
            return 4.4
        return 8.9 if prev == ',' else 7.3
    if token.strip() == 'dess':
        return 1.3
    if token == 'en' and re.search(r'\bdess$', tail):
        return 10.8
    if token == 'en' and re.search(r'\bder$', tail):
        return 6.7
    # Spanish cuyo/cuya and their partial spelling cuy, including in names.
    if token in ('uyo', 'uya', 'uyos', 'uyas') and prev == 'c':
        return 17.0 if token == 'uya' else 15.5
    if token == 'uy' and prev == 'c':
        return 8.0 if previous.strip() == 'C' else 13.7
    if token in ('os', 'as') and re.search(r'\bcuy$', tail):
        return 14.0
    if token in ('uyo', 'uya') and prev in ('s', 't'):
        return 1.5
    if token == 'ya' and prev == 'su':
        return 2.6
    # Russian possessive interrogatives/relatives: чей, чья, чьи, etc.
    if token in ('ь', 'ья', 'ей') and re.search(r'(?<!\w)ч$', tail):
        return {'ь': 12.4, 'ья': 11.0, 'ей': 9.0}[token]
    if word == 'чь':
        return 6.9
    if token in ('и', 'им', 'их', 'ей', 'его', 'ему', 'ю', 'я'):
        if re.search(r'(?<!\w)чь$', tail):
            return 12.3 if token == 'и' else 6.0
    # Italian relative cui: its possessive use follows an article.
    if word == 'cui':
        if prev in ('il', 'lo', 'la', 'i', 'gli', 'le'):
            return 15.0
        if prev in ('del', 'della', 'dello', 'delle', 'dei', 'degli',
                    'al', 'alla', 'ai', 'sul', 'sulla', 'nel', 'nella', 'dal'):
            return 13.5
        if prev in ('in', 'per'):
            return 0.0
        if prev == 'con':
            return 1.5
        if prev == 'a':
            return 2.2
        return 3.5
    # Latin genitive cuius, also spelled cujus.
    if token == 'j' and prev == 'cu':
        return 9.5
    if token == 'us' and prev == 'j' and re.search(r'\bcuj$', tail):
        return 5.6
    if token == 'us' and prev == 'cui':
        return 6.0
    if word == 'dont':
        if re.search(r'\b(façon|manière)\s*$', tail):
            return 0.2
        return 4.4 if FRENCH_CUES.search(tail.lower()) else -0.2
    if prev == 'dont' and token.strip() in ('l', 'la', 'le', 'les'):
        if re.search(r'\b(façon|manière) dont\s*$', tail):
            return 8.0
        return 8.7 if word == 'les' else 11.0
    if word in RELATIVES:
        return RELATIVES[word]
    if token == 'ท':
        return 0.6
    if token == 'ี่' and prev == 'ท':
        return 1.3
    if token.strip() in ('only', 'very') and prev == 'the':
        return 1.45 if word == 'only' else 1.35
    if word == 'of' and re.search(
        r'\bthe (kind|kinds|sort|sorts|type|types)\s*$', tail.lower()
    ):
        return 0.65 if prev in ('type', 'types') else 2.0
    if word == 'even' and prev in ("n't", 'n’t', "'t", '’t', 'not', 'cannot'):
        return 0.5 if prev == 'not' else 1.3
    if token == '··' and tail.endswith('··'):
        return -1.54
    return 0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, tail, previous = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, tail)
    return (doc, (tail + token)[-160:], token), value

"""Approximate a mixture of opening-token and small number-pattern responses.

At a document opening, C scalar-type spellings are strongly positive;
class/import spellings and short Markdown heading markers are negative. Ordinary
opening words receive a small positive baseline. A prefix consisting of
one repeated token keeps its opening response (including decorative runs).
After the opening, the main rules recognize 11/21/12, English eleven and
November, the URL separator, and the initial spelling Hy + dro. Unmodeled lexical variation
is left at zero. These are spelling rules, not a parser or a semantic claim
that, for example, every occurrence of 'char' really denotes a C type.
"""
READS = ()


def opening(s):
    word = s.lstrip('\t')
    if word == 'char':
        return 1.38 - 0.09 * (word != s)
    if word == 'void':
        return 1.62
    if word in ('int', 'bool'):
        return 1.20
    if word in ('float', 'double'):
        return 0.90
    if word in ('long', 'short', 'signed', 'unsigned'):
        return 0.45
    if s in ('class', 'from'):
        return -0.53
    if s == 'package':
        return -0.26
    if s in ('#', '##', '###'):
        return -0.75 + 0.167 * len(s)
    if s == '//\n':
        return 1.11
    if s == '/**':
        return -0.71
    if s == '··':
        return 0.886
    if s == '^^^^':
        return 1.28
    if s.startswith('<|'):
        return 0.02
    if s.isspace():
        if '\n' in s:
            return 0.134 * min(s.count('\n'), 2)
        if s == '\t':
            return 0.336
        if s == '\xa0':
            return 0.663
        return 0.025 if len(s) < 3 else -0.15
    if s.isascii() and s.isdigit():
        return -0.184 if s == '0' else (0.016 if s == '1' else -0.07)
    if s.strip().isalpha():
        return 0.18 if s.startswith(' ') else 0.14
    return 0.03


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        value = opening(s)
        return (doc, 1, s, value, True), value
    _, pos, prev, initial, uniform = carry
    uniform = uniform and s == prev
    value = 0.0
    if uniform:
        value = initial
    elif pos == 1 and prev == 'Hy' and s == 'dro':
        value = 2.40
    elif s == '1' and prev in ('1', '2'):
        value = 0.14
    elif s == '2' and prev == '1':
        value = 1.027 if pos == 1 else 0.047
    elif s.strip() == 'eleven':
        value = 0.25
    elif s.strip() in ('Nov', 'November'):
        value = 0.105 if s.strip() == 'Nov' else 0.145
    elif s == '://':
        value = -0.10
    return (doc, pos + 1, s, initial, uniform), value

"""A coarse document-opening pulse, rather than a vocabulary lookup.

Function-word classes and typography set the opening amplitude. It persists
through repetitions of the same opening token; ordinary later text gets zero.
Title: metadata and the numeric prefixes 12/122 get separate corrections.
Individual words' large, idiosyncratic opening values are not reproduced.
"""
from functools import lru_cache
import wordnet

READS = ()
# Closed-class grammar, grouped by the opening amplitudes observed in training.
CLASSES = (
    ('determiners', 'a an the this that these those', -0.5),
    ('core prepositions', 'of to in for at', -0.66),
    ('time/condition/contrast linkers',
     'if unless when while before after until once but yet', 3.15),
    ('past/perfect copula and do auxiliary', 'was were been do does did', 3.7),
    ('modals', 'can could shall should will would may might must', 1.4),
    ('personal pronouns', 'you he she me him her us them', 1.3),
    ('manner/reason questions', 'how why', 4.2),
    ('consequence connective', 'so', 4.2),
)
GRAMMAR = {w: a for _, words, a in CLASSES for w in words.split()}

@lru_cache(maxsize=10000)
def opening(s):
    t = s.strip()
    w = t.lower()
    if t == 'I':
        return 1.9
    if w in GRAMMAR:
        return GRAMMAR[w]
    if t.startswith('<|'):
        return 0.31
    if not t:
        return -1.28 if '\t' in s else 0.0
    if t.isdigit():
        return -0.18
    if t in ('.', '··', '․'):
        if '\n' in s:
            return 0.0
        return {'.': 1.84, '··': 7.6, '․': 3.19}[t]
    if t in '([{)]}':
        return -0.65
    if not t.isascii():
        return 0.8
    if not t.isalpha():
        return 0.0
    if len(t) == 1:
        return -0.43
    value = -0.08 + 0.98 * t.istitle() + 0.93 * s.startswith(' ')
    value += 0.75 * ('adverb' in wordnet.parts_of_speech(w))
    value -= 0.60 * ('noun.cognition' in wordnet.categories(w))
    return value


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, token, s, 0, True), float(opening(s))
    _, first_id, first_text, position, same = carry
    position += 1
    same = same and token == first_id
    value = opening(s) if same else 0.0
    if position == 1 and first_text == 'Title' and s == ':':
        value = 6.73
    if position == 1 and first_text == '1' and s == '2':
        value = -6.84
    if position == 2 and first_text == '1' and s == '2':
        if prefix.token_strings[-2] == '2':
            value = -2.47
    return (doc, first_id, first_text, position, same), float(value)

"""Detect mouth/opening morphemes, chiefly the Han character 口.

A standalone 口 or 一口 is strongest. Fused compounds are weaker, especially
technical interfaces, ports and windows. English mouth, Chinese 嘴 and the
Korean syllables gu and ip have smaller responses. The spelling kou and the
continuation -outh after m also respond. Selected k-i and k-u spelling
continuations have negative responses (including Cyrillic кук).
A separate small signal marks the old-range minus sign in a diff header.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = 0.0
    if '口' in word:
        if word in {'口', '一口'}:
            value = 8.0
        elif word == '人口':
            value = 5.8
        elif word in {'入口', '风口', '进出口'}:
            value = 5.1
        elif word in {'接口', '港口', '窗口'}:
            value = 0.8
        elif len(word) == 2:
            value = 3.8 if word.endswith('口') else 1.8
        else:
            value = 0.6
    elif '嘴' in word:
        value = 1.8
    elif lower in {'mouth', '-mouth', 'mouths'}:
        value = 2.6 if lower == 'mouths' else 2.0
    elif lower == 'outlet':
        value = 0.65
    elif word == '구':
        value = 0.85 if token[0].isspace() else 1.4
        if history.endswith(('입', '인', '수')):
            value = 5.5
    elif word == '입':
        value = 0.5
    elif lower == 'kou':
        value = 4.7
    elif token and not token[0].isspace() and history:
        last = history[-1].lower()
        if lower in {'ou', 'oup', 'our', 'ous'} and last == 'k':
            value = 2.4
        elif lower == 'outh' and last == 'm':
            value = 2.8
        elif lower == 'ou' and last == 'g':
            value = 1.1
        elif lower in {'ip', 'ips', 'ipp'} and last == 'k':
            value = -2.0
        elif lower == 'um' and last == 'k':
            value = -1.2
        elif lower == 'ук' and last == 'к':
            value = -2.0
    # A byte-split 口 responds when its final byte arrives.
    raw = prefix.token_bytes[-1]
    if history and raw.startswith(b'\xa3'):
        if prefix.token_bytes[-2].endswith(b'\xe5\x8f'):
            value = 8.0
    if word == '-' and history.rstrip().endswith('@@'):
        value = 0.85
    return (doc, (history + token)[-24:]), value

"""Sparse approximation emphasizing anomalous sentence endings.

An exclamation after a function word, or a dot/comma followed by an
exclamation, flags the current line as broken prose. Subsequent punctuation
gets a positive response; repeated endings alone give smaller boosts.
Independent rules cover Greek κ+αι, Python object inheritance, the headings
'Challenge Level' and 'Similar Topics', middle-dot ornaments, and several
opening fragments. Everything else is left near zero. These are recurring
patterns, not a reconstruction of the component's small background variation.
"""
import re

READS = ()
INCOMPLETE = set('a an the of to in for with from by as at and or'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    tail, marks, broken = ('', 0, False) if fresh else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    match = re.search(r'([^\W\d_]+)$', tail)
    previous = match.group(1).lower() if match else ''
    value = 0.0

    if token == 'αι' and tail.endswith('κ'):
        value = 0.73
    elif token == '··' and not tail.strip('·'):
        value = 0.87
    elif token == '(object' and re.search(r'\bclass\s+\w+\s*$', tail):
        value = 0.58
    elif (token.startswith('):')
          and re.search(r'\bclass\s+\w+\(object$', tail)):
        value = 0.35
    elif word == 'Level' and previous == 'challenge':
        value = -0.30
    elif token == 'Topics' and tail.endswith('Similar\n'):
        value = 0.80
    elif token and all(c in '.!,?' for c in token):
        mixed = token.endswith('!') and ('.' in token or ',' in token)
        incomplete = previous in INCOMPLETE
        broken = broken or mixed or (incomplete and token == '!')
        repeated = marks >= 2
        if mixed:
            value = 0.75 + 0.20 * incomplete
        elif token == '!':
            value = 0.035 + (0.55 if broken else 0.20 * repeated)
            value += 0.25 * incomplete
        elif token.count('.') >= 2 and set(token) <= {'.', ','}:
            value = -0.025 + (0.55 if broken else 0.10 * repeated)
            value += 0.15 * incomplete * broken
        elif token == '.':
            value = 0.18 * broken + 0.35 * (previous == 'the')
        if '!' in token or token.count('.') >= 2:
            marks += 1
    if fresh:
        if token == '.':
            value = -0.15
        elif token == ' .':
            value = 2.78
        elif token == '.\\':
            value = 1.58
        elif token == 'package':
            value = 1.28
    if '\n' in token:
        marks, broken = 0, False
    return (doc, (tail + token)[-100:], marks, broken), float(value)

"""Approximate a spelling response to t-l clusters, not a topic detector.

The strongest case is a short token ending in t followed by l or an
English-like -le ending. Contained clusters get smaller, spelling-dependent
values; continuations differ from space-prefixed words. Accented Latin and
Cyrillic letters are transliterated. Repeated middle dots have a separate
negative response. Other tokens are left at zero.
"""
import re
import regex
from anyascii import anyascii

READS = ()
LETTER_SCRIPTS = regex.compile(r'[\p{Latin}\p{Cyrillic}]')
L_ENDING = re.compile(r'l(?:e(?:[dst]|rs?)?|ings?)?\Z')
# Letters immediately before l; values for space-prefixed / unspaced tokens.
CONTAINED = (
    ('att', (0.69, 1.43)),
    ('ett', (5.13, 5.13)),
    ('rt', (3.83, 5.63)),
    ('st', (2.29, 3.28)),
)


def activation(token, previous):
    if len(token) > 1 and set(token) == {'·'}:
        return -0.56
    if not LETTER_SCRIPTS.search(token):
        return 0.0
    word = anyascii(token).lower()
    before = anyascii(previous).lower()
    if word.startswith('l'):
        ending = bool(L_ENDING.fullmatch(word))
        if before.endswith('t'):
            # A lowercase-to-uppercase boundary usually starts a new code word.
            if token[0].isupper() and previous[-1:].islower():
                return 0.12
            if word == 'l':
                return 7.58 if len(before.strip()) <= 4 else 0.96
            if ending:
                return 2.37 if word in ('ler', 'lers') else 4.83
            if word == 'ly':
                return 0.61
            return 2.16 if token.isupper() else 0.66
        if before.endswith('uck') and ending:
            return 4.54
    if before.endswith('t') and word.startswith('el') and len(word) <= 3:
        return 0.37

    cluster = re.search(r'(?:t|ck)l', word)
    if not cluster:
        return 0.0
    j = cluster.end() - 1
    lead, tail = word[:j], word[j:]
    compact = word.strip()
    if (len(compact) <= 5 and (token.islower() or token.isupper())
            and re.fullmatch(r'[a-z]*tl[rs]?', compact)):
        return 4.07  # Short TL abbreviations, including TLS and RTL.
    if lead.endswith('ck'):
        return 1.68 if lead.endswith('uck') and L_ENDING.fullmatch(tail) else 0.0
    if not L_ENDING.fullmatch(tail):
        return 0.0
    if lead.endswith(('itt', 'it')):
        return 0.16
    if tail in ('ler', 'lers', 'ling', 'lings'):
        return 0.44
    fragment = not token[:1].isspace()
    for letters, values in CONTAINED:
        if lead.endswith(letters):
            return values[fragment]
    return 5.19 if fragment else 0.10


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), activation(token, previous)

"""Partitive-looking phrases: a large negative pulse on 'one/any of'.

Weaker quantifiers such as 'all' give weaker pulses. Restrictive modifiers
('every one', 'the one') attenuate them. Common translations of 'one of'
are included. Articles and demonstratives have a small one-token echo.
A negative document-start bias and a secondary LaTeX row-break response
account for two other observed patterns; ordinary tokens predict zero.
"""
import re
import inflect

READS = ()
_numbers = inflect.engine()
CARDINALS = {_numbers.number_to_words(n) for n in range(1, 11)}
QUANTIFIERS = (
    ({'one', 'two', 'which'}, 1.4),
    (CARDINALS | {'any', 'many', 'several'}, 1.17),
    ({'some', 'none', 'neither', 'either'}, 1.04),
    ({'each', 'few'}, 0.92),
    ({'both'}, 0.72),
    ({'all', 'most', 'much', 'less', 'little', 'enough'}, 0.32),
    ({'half', 'couple'}, 0.12),
)
RESTRICTORS = {
    'the', 'every', 'each', 'any', 'only', 'exactly', 'single',
    'first', 'last', 'next', 'respective',
}
# Heads of common Romance and German phrases meaning 'one of'.
ONE_OF = {
    'de': {'uno', 'una', 'uma', 'un', 'une', 'um'},
    'des': {'un', 'une'},
    'das': {'um', 'uma'},
    'dos': {'um', 'uma'},
    'di': {'uno', 'una'},
    'delle': {'uno', 'una'},
    'der': {'ein', 'eine', 'einer', 'eines', 'einem', 'einen'},
}
COPULAS = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, tail, pulse = (doc, b'', 0.0) if first else carry
    token = prefix.token_strings[-1]
    word = token.strip().casefold()
    value = -0.23 if first else 0.0
    next_pulse = 0.0
    if word in {'of', 'among', 'из', '\\\\'} or word in ONE_OF:
        text = tail.decode('utf-8', errors='ignore')
        match = re.search(r'([^\W_]+)\s*$', text)
        previous = match[1].casefold() if match else ''
        words = re.findall(r'[^\W_]+', text.casefold())
        before = words[-2] if len(words) > 1 else ''
        if word == 'of':
            strength = next((s for group, s in QUANTIFIERS
                             if previous in group), 0.01)
            if previous.isdecimal():
                strength = 0.32
            if previous == 'more':
                strength = 1.0 if before == 'or' else 0.42
            if previous in CARDINALS:
                if before in RESTRICTORS:
                    strength *= 0.55
                elif before == 'no':
                    strength *= 0.25
            # Joined/camel-case forms are weaker than separate words.
            value = -strength * (1.0 if token[:1].isspace() else 0.4)
        elif word == 'among':
            value = -0.9 if previous in COPULAS else -0.1
        elif word == 'из':
            if previous == 'один' or previous.startswith('одн'):
                value = -1.3  # Russian forms of 'one'.
            elif previous.startswith(('кажд', 'люб', 'некотор')):
                value = -0.85  # Each, any, some.
        elif word in ONE_OF:
            if previous in ONE_OF[word]:
                value = -1.0 if word == 'der' else -1.3
            elif previous.startswith(('algun', 'algum')):
                value = -0.95  # Spanish/Portuguese forms of 'some'.
        else:
            math = re.search(r'\\[a-zA-Z]{2,}|[_^]', text)
            quoted = any(q in text for q in ('"', "'"))
            value = 0.7 if math and not quoted else -0.15
        if word != '\\\\':
            next_pulse = value
    elif pulse < -0.25:
        if word == 'the':
            value = 0.12 * pulse
        elif word in {'these', 'those', 'this'}:
            value = -0.14 * pulse
        elif word in {'los', 'las'}:
            value = 0.4 * pulse
    return (doc, (tail + prefix.token_bytes[-1])[-128:], next_pulse), value

"""Approximate a multilingual particle / inflection-ending signal.

The strongest rules describe Korean consonant-conditioned particles: the same
particle can be positive after a closed syllable and negative after a vowel.
Other small rules cover Japanese particles, Greek inflectional sequences,
Russian vowel + у junctions, Persian suffixes and repeated middle-dot dividers.

Finnish-looking context gates a short list of suffix spellings and fragments.
Its confidence uses completed words' relative corpus frequencies, with ä/ö as
evidence and other languages as counter-evidence. Unmatched tokens receive no
Finnish contribution. These are surface heuristics, not a grammatical parser.
UTF-8 fragments are joined; state resets at document boundaries.
"""
import codecs
import unicodedata
from functools import lru_cache

from wordfreq import zipf_frequency

READS = ()

# Baselines for Korean case, topic and relational particles.
KOREAN = {
    '을': 1.25,
    '은': 0.78,
    '이': 0.88,
    '를': 1.12,
    '가': 0.82,
    '는': 0.45,
    '로': 0.65,
    '과': 0.62,
    '와': 0.60,
    '으로': 0.55,
    '의': 0.22,
    '에': 0.25,
    '도': 0.25,
}
JAPANESE = {
    'を': 0.75,
    'が': 0.84,
    'も': 0.20,
    'は': 0.16,
}


def hangul_parts(ch):
    """The vowel and optional final consonant of a Korean syllable."""
    if unicodedata.name(ch, '').startswith('HANGUL SYLLABLE '):
        parts = unicodedata.normalize('NFD', ch)
        return parts[1], parts[2:]
    return None


def surface_response(carry, prefix):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '')
    _, pending, tail = carry
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[used:]
    token = prefix.token_strings[-1]
    bare = token.strip().lstrip('\ufffd')
    full = tail + text
    value = JAPANESE.get(token, 0.0)
    if bare in KOREAN:
        before = full[:-len(bare)].rstrip()
        ch = before[-1:] or ' '
        parts = hangul_parts(ch)
        value = KOREAN[bare]
        if parts:
            vowel, coda = parts
            if not coda:
                if bare == '을':
                    value = -2.5 if vowel == 'ᅳ' else -8.0
                elif bare == '은':
                    value = -7.0 if vowel == 'ᅵ' else -5.8
                elif bare == '이':
                    if vowel == 'ᅵ':  # Repeated i vowel.
                        value = -6.0
                    elif vowel in {'ᅦ', 'ᅧ'}:  # e / yeo vowels.
                        value = -1.6
                    else:
                        value = -2.9
                elif bare == '과':
                    value = -3.0
            elif bare in {'가', '는', '와'}:
                value = 0.1
            elif bare == '로' and coda != 'ᆯ':  # ㄹ permits 로, like no coda.
                value = 0.2
        elif bare == '이':
            value = 0.1
        if token.startswith('\ufffd'):
            value *= 0.7
    elif token in {'ها', 'ای'}:
        value = 0.5
    elif token == 'у':
        prev = tail[-1:].lower()
        value = 0.22
        if prev in {'о', 'е', 'ё'}:
            value = -4.5
        elif prev in {'а', 'у', 'я', 'ю'}:
            value = -1.2
        elif not tail:
            value = -2.3
    elif token == ' а':
        value = -0.3
    if bare in {'ν', 'σ', 'ς'}:
        before = full[:-1]
        if before.endswith(('ού', 'οὺ')):
            value = {'ν': 4.8, 'σ': 4.3, 'ς': 2.2}[bare]
        elif bare == 'ν' and before.endswith('ου'):
            value = 0.8
        elif bare == 'ν' and before.endswith(('ω', 'ώ', 'ῶ')):
            value = 0.4
        elif bare == 'ν':
            value = -0.12
    elif bare == 'ί' and full.endswith('εί'):
        value = 2.3 if len(full) > 2 and full[-3].isalpha() else 1.1
    elif bare == 'ι' and full.endswith('ει'):
        value = 0.45
    elif bare == 'ε' and full.endswith('ίε'):
        value = 0.6
    if token == '··' and (not tail or tail.endswith('·')):
        value = -1.86
    if token == '<|endoftext|>':
        pending, full = b'', ''
    return (doc, pending, full[-24:]), float(value), text


@lru_cache(maxsize=30000)
def word_evidence(word):
    if len(word) < 2:
        return 0.0
    fi = zipf_frequency(word, 'fi')
    en = zipf_frequency(word, 'en')
    if en > max(fi + 1.0, 4.5):
        return -0.6
    other = max(en, max(zipf_frequency(word, lang)
                        for lang in ('de', 'sv', 'hu')))
    if other > max(fi + 1.0, 4.5):
        return -0.6
    return 1.0 if fi >= 2.0 and fi > other + 1.0 else 0.0


def finnish_context(state, text):
    word, support, accents = state
    for ch in text:
        if ch.lower() in 'äö':
            accents = min(5.0, accents + 1.0)
        if ch.isalpha():
            word = (word + ch.lower())[-60:]
        elif word:
            support = min(5.0, max(0.0, 0.96 * support + word_evidence(word)))
            accents *= 0.95
            word = ''
    if 'õ' in text.lower():  # A characteristic Estonian vowel.
        support, accents = 0.0, 0.0
    confidence = min(1.0, max(0.0, (support - 0.5) / 1.5))
    confidence *= min(1.0, accents / 1.5)
    return (word, support, accents), confidence


def finnish_ending_value(token, before):
    """Match selected Finnish suffix spellings, not a full morphological parse."""
    word = token.strip().lower()
    if word == 'on' and (token[:1].isspace() or not before):
        return 5.0  # Finnish copula.
    if word in {':n', ':ssa', ':lla'}:
        return 8.0  # Case suffixes appended to abbreviations.
    if token[:1].isspace() or not word.isalpha():
        return 0.0
    if word.endswith(('ille', 'elle')):
        return 8.0  # Allative.
    if word.endswith(('ssa', 'ssä', 'sta', 'stä', 'lla', 'llä',
                      'lta', 'ltä', 'lle', 'ksi')):
        return 5.0  # Cases.
    if word.endswith(('mme', 'nsa', 'nsä')) or (
        word == 'me' and before.endswith('m')
    ):
        return 7.0  # Person/possessive endings.
    if word in {'ni', 'si'}:
        return 3.5
    if word in {'ss', 'll', 'ks', 'iss', 'ess', 'uss', 'ill'}:
        return 4.0  # Token fragments of case endings.
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0][0] != doc:
        carry = (None, ('', 0.0, 0.0))
    letters, finnish = carry
    before = letters[2] if letters else ''
    letters, value, text = surface_response(letters, prefix)
    finnish, confidence = finnish_context(finnish, text)
    token = prefix.token_strings[-1]
    if confidence:
        value += confidence * finnish_ending_value(token, before)
    if token == '<|endoftext|>':
        finnish = ('', 0.0, 0.0)
    return (letters, finnish), float(value)

