"""layers.1.mlp.down_proj:2697 — case endings in case-marking languages.

Fires on the grammatical-case or inflectional ending of a word in languages that mark
case by suffixes or particles:
  * Japanese particles が and を (subject / object), plus は and も weakly (not included here);
  * Korean case particles 를, 을 (object), 가 (subject), 은/는 (topic), 와/과, 로/으로;
  * Greek verb endings ί, Hungarian case endings -ban and -ól;
  * Finnish: inside Finnish text (detected by common Finnish function words seen so far in the
    document), every word-internal piece (a token with no leading space) gets a moderate
    activation, and Finnish case endings (-ksi, -ää, -ään, -itä, -ista, -ä, -aa) a larger one.
Everything else is predicted as 0.
"""

READS = ()

CASE_PARTICLES = {
    "が": 0.85, "を": 0.75,                      # Japanese
    "를": 1.1, "을": 0.9, "가": 0.7, "은": 0.5, "는": 0.4,  # Korean
    "와": 0.5, "과": 0.4, "로": 0.5, "으로": 0.5,
    "ί": 0.6, "ban": 0.7, "ól": 0.7,            # Greek, Hungarian
}

FINNISH_ENDINGS = {"ksi": 3.0, "ää": 3.0, "ään": 4.0, "itä": 2.7, "ista": 0.9, "ä": 0.4, "aa": 0.6}

FINNISH_WORDS = set(
    "että mutta kuin myös sekä tämä hän niin ovat kanssa joka kun sitä hänen kaikki "
    "paljon mukaan kuitenkin vain tai vielä olla".split()
)
FINNISH_MIN_WORDS = 3     # Finnish function words seen in this document before we call it Finnish
FINNISH_PIECE = 1.0       # activation for a word-internal piece in Finnish text


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    seen = carry[1] if carry is not None and carry[0] == doc else 0   # Finnish words so far
    tok = prefix.token_strings[-1]
    if tok.startswith(" ") and tok.strip() in FINNISH_WORDS:
        seen += 1
    value = CASE_PARTICLES.get(tok, 0.0)
    if tok in FINNISH_ENDINGS:
        value = FINNISH_ENDINGS[tok] if seen >= FINNISH_MIN_WORDS else max(value, 0.4 * FINNISH_ENDINGS[tok])
    if seen >= FINNISH_MIN_WORDS and tok.isalpha() and not tok.startswith(" "):
        value = max(value, FINNISH_PIECE)
    return (doc, seen), float(value)

programs.sol:
"""A coarse grouping-punctuation and indentation signal.

Ordinary text stays near zero. Grouping marks, quotes, code keywords and math
command names get family-specific estimates, modulated by visible nesting and
recent grouping-mark density. Tabs and spaces provide indentation cues. This
captures broad formatting patterns, not token-specific or detailed syntax effects.
State resets between documents; an initial "Title:" heading is a fixed negative
exception observed in training.
"""
from functools import lru_cache

READS = ()
CODE_WORDS = frozenset((
    'if for while else elif try catch finally return switch case '
    'break continue do throw def function class public private '
    'protected static void const let var import from'
).split())
MATH_WORDS = frozenset((
    'frac dfrac tfrac left right begin end mathrm mathbf mathit '
    'operatorname sqrt sum prod int lim ensuremath'
).split())


@lru_cache(maxsize=200000)
def family(s):
    a = s.strip()
    if not a:
        return 'indentation'
    if '{' in a:
        return 'curly_both' if '}' in a else 'curly_open'
    if '}' in a:
        if '"' in a and '\n' in s:
            return 'quoted_curly_end'
        return 'curly_close'
    if '[' in a or ']' in a:
        return 'square'
    if '(' in a or ')' in a:
        return 'round'
    if '\\' in a:
        return 'backslash'
    if '"' in a:
        return 'json_key_end' if ':' in a else 'quote'
    if "'" in a:
        return 'quote'
    if a in CODE_WORDS:
        return 'code_word'
    if a in MATH_WORDS:
        return 'math_word'
    if a.endswith('Box'):
        return 'box_suffix'
    if any(c.isalpha() or c.isdigit() for c in a):
        return 'ordinary'
    return 'punctuation'


# Each row weights: baseline, inside-curly, extra curly nesting,
# square nesting, recent grouping density, tabs, spaces.
WEIGHTS = {
    'backslash': (
        -0.045, 0.165, 0.035, 0.129, 0.151, 0.0, 0.061,
    ),
    'code_word': (
        -0.014, 0.095, 0.049, 0.002, 0.026, 0.005, 0.006,
    ),
    'curly_both': (
        0.189, 0.162, 0.182, 0.202, -0.033, 0.0, -0.054,
    ),
    'curly_close': (
        -0.021, 0.377, 0.188, 0.226, 0.252, 0.0, 0.008,
    ),
    'curly_open': (
        0.06, 0.023, 0.148, 0.207, 0.271, 0.0, 0.06,
    ),
    'indentation': (
        -0.001, 0.062, 0.087, 0.059, -0.047, 0.041, 0.002,
    ),
    'json_key_end': (
        0.003, -0.007, 0.033, 0.083, -0.718, 0.0, -0.061,
    ),
    'math_word': (
        0.052, 0.167, 0.092, 0.162, 0.155, -0.274, -0.081,
    ),
    'box_suffix': (
        0.264, -0.1, -0.077, 0.084, 0.046, 0.0, -0.241,
    ),
    'ordinary': (
        0.001, -0.005, 0.003, -0.013, -0.012, 0.006, -0.001,
    ),
    'punctuation': (
        0.007, 0.032, 0.021, 0.011, 0.015, 0.0, -0.006,
    ),
    'quote': (
        0.021, 0.051, 0.055, 0.144, -0.051, 0.0, 0.014,
    ),
    'quoted_curly_end': (
        -0.139, 0.088, 0.139, 0.054, -0.095, 0.0, 0.049,
    ),
    'round': (
        -0.023, 0.074, 0.035, 0.196, 0.116, 0.0, 0.006,
    ),
    'square': (
        -0.088, 0.038, 0.035, 0.239, 0.29, 0.0, -0.082,
    ),
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, 0, 0.0, '')
    _, position, curly, square, recent, previous = carry

    # Bounded net counts are only a rough nesting estimate, not a parser.
    curly = max(-15, min(15, curly + s.count('{') - s.count('}')))
    square = max(-15, min(15, square + s.count('[') - s.count(']')))
    grouping = sum(s.count(c) for c in '{}[]()')
    recent = 0.85 * recent + 0.15 * grouping
    features = (
        1.0,
        float(curly > 0),
        min(max(curly - 1, 0), 4),
        min(max(square, 0), 6),
        recent,
        min(s.count('\t'), 6),
        min(s.count(' '), 32),
    )
    value = sum(w * x for w, x in zip(WEIGHTS[family(s)], features))

    # The initial "Title:" document-heading format has a negative exception.
    if position == 0 and s == 'Title':
        value = -0.567
    elif position == 1 and previous == 'Title' and s == ':':
        value = -3.896

    state = (doc, position + 1, curly, square, recent, s)
    return state, float(max(-3.9, min(5.0, value)))

"""A lexical grouping/ancestry signal, with a second spelling response to z+vowel.

Bare Chinese/Japanese group characters are strongly negative; larger words
containing them are weaker. Korean jo and Vietnamese to (with a hook and
circumflex) share the negative response. A split Latin spelling after z also
elicits a negative value, especially the syllable zong. Ordinary tokens are
near zero. English "group" gets a weak context-dependent response: negative
for abstract algebra/chemistry, positive after human-group qualifiers.
Text beginnings and repeated middle dots get small positive values.
"""

import re

READS = ()
ABSTRACT = re.compile(
    r'\b(?:abelian|algebraic|algebra|cyclic|renormalization|symmetry|'
    r'quotient|subgroups?|semisimple|unipotent|hydroxyl|functional|'
    r'polar|carbon|chemical|ring|divisibility)\b', re.I)
PEOPLE = re.compile(
    r'\b(?:large|small|this|that|these|those|both|each|other|two|three|'
    r'different|same|specific|control|experimental|militia|working|'
    r'ethnic|social|political|diagnostic)\s*$', re.I)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, tail, history = '', b'', ''
        first = True
    else:
        _, prev, tail, history = carry
        first = prev == '<|endoftext|>'
    word = s.strip()
    value = 0.0

    if '组' in word or '組' in word:
        if word in ('组', '組', '一组', '一組'):
            value = -5.3 if '組' in word else -4.7
        elif '组合' in word or '組合' in word:
            value = -2.5
        else:
            value = -1.6
    elif word == '祖':
        value = -6.4
    elif word == '宗':
        value = -3.3
    elif word in ('祖父', '祖母', '祖先'):
        value = -1.1
    elif word == '조':
        value = -3.5 if s.startswith(' ') else -2.1
    elif word == '조직':
        value = -2.1
    elif word.lower() == 'tổ':
        value = -8.8

    # Partial UTF-8 spelling: 組, 結, 統, 終 share the bytes E7 B5.
    joined = tail + b
    if b == b'\xb5' and tail.endswith(b'\xe7'):
        value = -3.9
    elif b == b'\x84' and tail.endswith(b'\xe7\xbb'):
        value = -5.0
    elif b == b'\x96' and tail.endswith(b'\xe7\xa5'):
        value = -6.4
    elif b == b'\x97' and tail.endswith(b'\xe5\xae'):
        value = -5.0
    elif prev.endswith('組') and word in ('み', '合'):
        value = -0.7 if word == 'み' else -2.8

    # A syllable divided immediately after z, as in Z|ulu or z|ong.
    if prev.lower().endswith('z') and s:
        sound = s.lower()
        if sound.startswith(('o', 'u')):
            value = -0.2
            if sound == 'u':
                value = -1.4
            elif sound == 'ong':
                value = -4.2
            elif sound == 'om':
                value = -1.6
        elif sound == 'hu':  # z + hu spells the Mandarin initial zh.
            value = -2.4
    elif s == 'izu':
        value = -4.0
    elif s == 'zu':
        value = -0.7

    if word.lower() in ('group', 'groups', '-group', '-groups', 'subgroup'):
        if prev.lower().endswith('sub') or word.lower() == 'subgroup':
            value = -0.55
        elif ABSTRACT.search(history):
            value = -0.3
        elif PEOPLE.search(history):
            value = 0.25

    if first and s[:1].isascii():
        if s[:1].isalpha():
            value += 0.2 if s[:1].isupper() else 0.15
        elif s[:1].isdigit():
            value += 0.11
    if s == '··' and prev.endswith('·'):
        value = 0.4
    return (doc, s, joined[-3:], (history + s)[-128:]), value

programs.haiku:
"""Group/organisation words in CJK scripts (组 and 組 = group, team, set; 组织 = organisation;
Korean 조 and Vietnamese Tổ = group; 宗/祖 = clan/ancestor). The activation is strongly negative
on these tokens and near zero elsewhere."""
READS = ()
BARE_GROUP = {"组", "組", "조", "Tổ"}          # the group word on its own
GROUP_CHARS = "组組"                           # group character inside compounds
CLAN_CHARS = "宗祖"

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    if tok in BARE_GROUP:
        return carry, -5.0
    if any(c in tok for c in GROUP_CHARS):
        return carry, -2.0
    if any(c in tok for c in CLAN_CHARS):
        return carry, -3.0
    return carry, 0.0

programs.sol:
"""A partial explanation in local phrases and typography.

Predict negative pulses on familiar English links ('starting at', 'as if',
'lack of'), and positive pulses on numeric labels after dashes, introductory
commas, and several phrasal verbs. Most other tokens receive nearly zero.
This is a mixed local detector, not one unified semantic category. Rounded
constants summarize training observations; many lexical effects are omitted.
A separate lexical rule marks completion of 'weightage'. Only a short suffix
and the previous token are retained, resetting per document.
"""
import re

READS = ()
DASHES = '-–—−'
COPULAS = {'is', 'are', 'was', 'were', 'be', 'being', 'been'}
LABELS = {'exercise', 'set', 'step', 'problem', 'problems', 'chapter'}
CHANGE = {
    'increase', 'improvement', 'advancement', 'change', 'changes',
    'generation', 'reduction',
}
KNOWLEDGE = {'understanding', 'awareness', 'knowledge', 'appreciation'}
ABUNDANCE = {'wealth', 'abundance', 'diversity', 'plethora'}
DISCOURSE = {
    'alternatively', 'example', 'instance', 'actually', 'specifically',
    'interestingly', 'besides', 'moreover', 'thus', 'therefore',
}


def activation(s, previous, tail):
    w, p = s.strip().lower(), previous.strip().lower()
    dash_before = bool(p) and all(c in DASHES for c in p)
    # A colon-dash introduces a list; a word-dash-number forms a label.
    if ':' in w and any(c in DASHES for c in w):
        if all(c in DASHES + ':' for c in w):
            return 0.85
    if re.search(r':[-–—−]\s*$', tail) and s.isspace():
        return 0.85
    if w.isascii() and w.isdigit() and re.search(r'[-–—−]\s*$', tail):
        left = re.sub(r'[-–—−]\s*$', '', tail).rstrip()
        word = re.search(r'([A-Za-z]+)$', left)
        if word and word.group(1).lower() in LABELS:
            return 1.5
        return 0.21 if word else 0.04
    if s.isspace() and dash_before:
        left = re.sub(r'[-–—−]\s*$', '', tail).rstrip()
        word = re.search(r'([A-Za-z]+)$', left)
        return 0.72 if word and word.group(1)[0].isupper() else 0.2
    if w in {'at', 'in'} and p in {'start', 'starts', 'starting', 'started'}:
        return -1.66 if w == 'at' else -0.58
    if p == 'as':
        if w in {'if', 'though'}:
            return -1.16
        if w == 'in':
            return -0.65
        if w in {'being', 'above', 'for', 'soon', 'any', 'long'}:
            return -0.45
        if w == 'per':
            return 0.69
        if w == 'under':
            return 1.59
    if w == 'of':
        if p == 'which':
            return -1.04
        if p in {'lack', 'loss'}:
            return -0.71 if p == 'lack' else -0.5
        if p in CHANGE:
            return -0.47
        if p in KNOWLEDGE:
            return -0.45
        if p in ABUNDANCE:
            return -0.6
        if p in {'comprises', 'comprised', 'working'}:
            return 0.91
    if w.startswith(','):
        if p == 'however':
            return 0.49 if previous.strip() == 'however' else 0.09
        if p in {'namely', 'especially', 'particularly'}:
            return 0.83
        if p in DISCOURSE:
            return 0.14
        if p in COPULAS:
            return 0.2
        if '\n\n' in s and p in {'that', 'where', 'given'}:
            return 0.61
        return 0.01
    if w == 'as' and p in {'termed', 'called', 'named'}:
        return 1.15
    if w == 'in' and p in {'help', 'helps', 'helped', 'helping'}:
        return 0.92
    if w == 'in' and p in {'especially', 'particularly', 'rich'}:
        return -0.49
    if w in {'if', 'though'} and p == 'even':
        return -0.3
    if w == 'also' and p == 'but':
        return -0.44
    if w == 'and' and dash_before:
        return -0.39
    if w == 'off' and p in {'round', 'rounded', 'rounding'}:
        return 0.79
    if w == 'into' and p in {'look', 'looks', 'looking', 'looked'}:
        return 0.61
    if w == 'down' and p in {'note', 'noted', 'notes', 'noting'}:
        return 1.0
    if w == 'bigger':
        return 0.99 if p in {'a', 'the', 'an'} else 0.19
    if p == 'relatively' and w in {
        'larger', 'better', 'higher', 'lower', 'cheaper', 'more'
    }:
        return 1.46
    if w == 'age' and p == 'weight':
        return 3.0
    if w in {'even', 'between', 'under', 'each'}:
        return {'even': -0.22, 'between': -0.11,
                'under': 0.12, 'each': 0.09}[w]
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    s = prefix.token_strings[-1]
    value = activation(s, previous, tail)
    return (doc, s, (tail + s)[-96:]), value

programs.haiku:
"""Layer-1 MLP hidden unit 2701 of Qwen3-1.7B, written to the down projection.

Plain-terms description: a mostly quiet unit whose large responses come from a few
phrases, and whose small responses come from a few word classes. Each rule below predicts
the unit's activation at the current token from the token and the word before it.
  - "of" after a noun of change or lack (increase, loss, lack, wealth, understanding) is
    pushed negative; "of" after a part or measure noun (piece, part, set, years, front) is
    pushed positive;
  - the word after "as" in "as if", "as in", "as though" is pushed negative, and so is "at"
    or "in" after "starting" or "start";
  - "even if" and "but also" are pushed negative;
  - a comma after a connective ("however,", "namely,", "Alternatively,", "for example,") is
    pushed positive;
  - a space after a dash ("word – next") is pushed positive, and a digit after a hyphen
    (product or model codes such as "SET-2") is pushed slightly positive;
  - the first token of each document is pushed slightly positive;
  - emphasis adverbs ("even", "especially", "widely", "also") are pushed slightly negative.
Everything else predicts 0.
"""

READS = ()

DOC_START = 0.12
CHANGE_NOUNS = {" lack", " loss", " wealth", " increase", " decrease", " reduction",
                " improvement", " advancement", " rise", " drop", " growth", " gain",
                " change", " shift", " understanding", " knowledge", " awareness",
                " diversity", " depletion", " decline"}
PART_NOUNS = {" piece", " part", " set", " front", " back", " years", " months", " comprised",
              " comprises"}
AS_FOLLOWERS = {" if", " in", " though", " being", " for", " soon", " above", " any"}
START_WORDS = {" starting", " start", " starts", " started", "Starting", "Start"}
CONNECTIVES = {"however", "namely", "Alternatively", "example", "Thus", "instance", "Like", "particularly"}
DASHES = {" -", " –", " —", "-", "–", " −"}
EMPHASIS = {" even", " especially", " particularly", " widely", " also"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, DOC_START
    prev = prefix.token_strings[-2]
    if cur == " of":
        if prev in CHANGE_NOUNS:
            return carry, -0.6
        if prev in PART_NOUNS:
            return carry, 0.2
    if prev == " as" and cur in AS_FOLLOWERS:
        return carry, -0.7
    if prev in START_WORDS and cur in (" at", " in"):
        return carry, -1.6
    if cur == " if" and prev in (" even", " Even"):
        return carry, -0.4
    if cur == " also" and prev == " but":
        return carry, -0.4
    if cur == "," and prev in CONNECTIVES:
        return carry, 0.2
    if cur == " " and prev in DASHES:
        return carry, 0.35
    if prev == "-" and cur.isdigit():
        return carry, 0.1
    if cur in EMPHASIS:
        return carry, -0.2
    return carry, 0.0

programs.sol:
"""Recognize programming-language names and source-file suffixes.

The positive signal is mostly on the name itself (also when split across
subwords), rather than on arbitrary code. Python, TypeScript, Go and source
extensions are strong; shell, markup and non-source suffixes are weak. A separate
coarse correction handles document starts and constant-token prefixes,
including script, whitespace and punctuation effects.
"""
import re
import unicodedata

READS = ()

LANGUAGES = {
    'python': 0.85, 'javascript': 0.7, 'typescript': 1.4,
    'ruby': 0.95, 'rust': 1.05, 'php': 0.9, 'perl': 0.95,
    'cpp': 1.05, 'kotlin': 1.3, 'groovy': 1.1, 'golang': 1.65,
}
STRONG_EXTENSIONS = {'py', 'ts', 'go', 'java'}
OTHER_EXTENSIONS = {'rs', 'cpp', 'hpp', 'cs', 'rb', 'swift', 'jsx', 'tsx'}
NON_SOURCE_EXTENSIONS = {
    'txt', 'json', 'yaml', 'yml', 'xml', 'ini', 'cfg', 'conf',
    'md', 'csv', 'zip', 'jar',
}


def initial_value(s):
    """Formatting and script, not a vocabulary lookup, at a fresh start."""
    if s == '<|endoftext|>':
        return 4.5
    if s.startswith('<|'):
        return 0.0
    if s.isspace():
        if '\r' in s:
            return -3.8
        if '\n' in s:
            return -1.1 if s == '\n\n' else 1.1
        return (1.2 if s == ' ' else 2.0) if s.isascii() else -1.0
    t = s.strip()
    if '\ufffd' in t:
        return 0.9
    if t.isdecimal():
        return 1.0
    if any(c.isalpha() and not ('LATIN' in unicodedata.name(c, ''))
           for c in t):
        return 1.1
    if t.isalpha():
        return -0.4 if t.istitle() else -0.2
    if not any(c.isalnum() for c in t):
        if len(t) > 1 and set(t) == {'^'}:
            return -5.7
        if s == '//\n':
            return -5.8
        if set(t) == {'·'}:
            return 0.54
        if t == '.':
            return 4.0 if s.endswith('.\n') else 1.5
        if '\n' in s:
            return 1.5
        if '"' in t or '“' in t:
            return 2.2
        if t in {',', ':', ';'}:
            return 0.05
        if t in {'(', ')', '[', ']', '{', '}'}:
            return 0.1 if s.startswith(' ') else 1.1
        if set(t) == {'_'}:
            return 1.4
        return 0.3
    return 0.0


def lexical_value(s, before):
    t = s.strip()
    word = t.lstrip('./_-').lower()
    joined = before + s
    # Names can cross tokenizer boundaries: r + uby, Type + Script, etc.
    for name, value in LANGUAGES.items():
        if word == name:
            if name == 'python' and t.startswith('/'):
                return 1.4
            if name == 'python' and t.startswith(('.', '-')):
                return 2.2
            return value
        if t.isalpha() and len(t) >= 3 and len(t) < len(name):
            if joined.lower().endswith(name):
                return value + (0.25 if name in {'ruby', 'typescript'} else 0)
    if t.startswith('.'):
        ext = t[1:]
        if ext in STRONG_EXTENSIONS:
            return 0.98
        if ext == 'js':
            return 0.8
        if ext == 'php':
            return 0.6
        if ext in OTHER_EXTENSIONS:
            return 0.38
        if ext in NON_SOURCE_EXTENSIONS:
            return -0.22
    if word == 'py':
        if t.startswith('_'):
            return 1.9
        if s == ' Py' or s == 'PY':
            return 0.12
        return 1.4 if t.startswith('/') else 0.95
    if word == 'js':
        return 1.4 if before.endswith('```') else 0.65
    if word == 'ts':
        return 1.2 if t.startswith('/') else (0.35 if s == ' TS' else 0.0)
    if word == 'java':
        if t.startswith('/'):
            return 0.35
        return 0.2 if t == 'java' and s[0].isspace() else 0.7
    if word == 'go':
        if t.startswith(('/', '-')):
            return 1.7
        if re.search(r'(\s{2,}|[`"\n\t]|&&\s*)$', before):
            return 1.0
        if re.search(r'\b(go\.(mod|sum)|func|golang)\b', before):
            return 0.8
        return 0.15 if s.startswith(' ') else 0.4
    if word == 'node':
        if t.startswith(('/', '-')) or t.isupper():
            return 0.85
        return 0.65 if re.search(r'(&&\s*|\n +|`)$', before) else 0.15
    if word == 'react':
        return 0.8 if not s.startswith(' ') or t.istitle() else 0.0
    if t in {'#', 'sharp', '++'} and re.search(r'\b[cC]$', before):
        return 2.7 if t != '++' else 1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        before, first, repeated = '', s, True
    else:
        _, before, first, repeated = carry
        repeated = repeated and s == first
    value = initial_value(s) if repeated else lexical_value(s, before)
    return (doc, (before + s)[-400:], first, repeated), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:2702 -- a "programming language name / source-file extension" detector.

It is near zero on most text. It rises on the names of programming languages and frameworks
(python, Go, TypeScript, React, Node, ...) and on their file extensions or path pieces
(".py", ".ts", "/go", "-python"), which is where the component's activation is largest. A
first token of a packed row gets its own rule, since the model has no context there.

Plain-language rule, per token:
  - first token of a row: about -0.2 for a space-led word, +0.2 for a bare word, +1 otherwise;
  - a run of middle dots (U+00B7): +0.5;
  - a carriage return or "^^^^": -0.7;
  - a language or extension right after ./-_ (a file or path piece): +1.0;
  - a language or framework name as a word: +0.7;
  - anything else: 0.
"""

READS = ()

# Language and framework names, as words.
NAMES = {
    "python", "javascript", "typescript", "java", "php", "ruby", "rust", "golang", "react",
    "node", "perl", "kotlin", "swift", "scala", "dart", "cpp", "csharp", "sharp", "js", "py", "go",
}
# File extensions (and short names) that count as a language after a path separator.
EXTS = {
    "py", "js", "ts", "go", "java", "php", "rb", "rs", "cpp", "cs", "hpp", "jsx", "tsx", "pyx",
    "kt", "node", "react",
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    if prefix.position == 0:
        if raw.startswith(" ") and raw.strip().isalpha():
            return None, -0.2
        if raw.isalpha():
            return None, 0.2
        return None, 1.0
    if raw and set(raw) == {"·"}:
        return None, 0.5
    if raw == "\r" or raw == "^^^^":
        return None, -0.7
    if raw[:1] in "./-_" and raw[1:].lower() in EXTS | NAMES:
        return None, 1.0
    if raw.strip().lower() in NAMES:
        return None, 0.7
    return None, 0.0

programs.sol:
"""Predict chat delimiters and short q-bearing spelling fragments.

Tool-call endings are strongly negative; message endings are weaker after
calls and responses. Arabic qaf (ق) is negative, especially in short fragments
and with following ya (قي). Attached suffixes inherit a fading negative value.
Two-letter a/i fragments after Latin Q/q are also negative; TeX qquad is
positive. A document-initial 'Title:' header has a negative colon.
"""
import regex

READS = ()
DELIMITERS = {
    '</tool_call>': -6.9,
    '<tool_call>': -4.0,
    '<tool_response>': -1.76,
    '</tool_response>': 0.73,
    '<think>': 0.91,
    '</think>': 0.22,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, last_nonspace, echo, position = '', '', 0.0, 0
    else:
        _, previous, last_nonspace, echo, position = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    latin = token.isascii() and token.isalpha()
    arabic = bool(regex.fullmatch(r'[\p{Script=Arabic}\p{M}]+', token))
    value = echo if latin or arabic else 0.0
    echo = value * 0.55

    if 'ق' in token:
        length = len(regex.findall(r'\p{L}', token))
        strength = (0, 7.2, 4.8, 3.8, 2.1, 1.2, 0.6)
        value = -strength[length] if length < len(strength) else 0.0
        if length == 2 and 'قي' in token:
            value -= 3.0
        echo = value * 0.7
    elif latin and previous.lower().endswith('q'):
        if token == 'quad':  # Split spelling of the TeX command \qquad.
            value, echo = 3.9, 0.0
        elif token[0].lower() in 'ai':
            if len(token) == 2:
                value = -6.2
            elif len(token) == 1:
                value = -1.2
            else:
                value = -4.0 if token[0].lower() == 'a' else -0.3
            echo = value * 0.45
    elif word.isascii() and word.isalpha() and len(word) > 1:
        if word[0] == 'q' and word[1] in 'aeio':
            value = -3.0 if word[1] in 'ao' else -2.0

    if token in DELIMITERS:
        value = DELIMITERS[token]
    elif token == '<|im_end|>':
        value = -2.4
        if last_nonspace == '</tool_response>':
            value = -1.17
        elif last_nonspace == '</tool_call>':
            value = -1.8
    elif token == ':' and previous == 'Title' and position == 1:
        value = -6.95

    if token.strip():
        last_nonspace = token
    return (doc, token, last_nonspace, echo, position + 1), value

"""Approximate a language-sensitive response to t-bearing word pieces.

Cyrillic soft-t endings and Czech/Slovak/Polish t or palatal consonant
fragments are positive cases, not a syntactic test for infinitives. Recent
word frequencies gate Latin-script responses; Ukrainian letters strengthen
Cyrillic continuations. Arabic ta is negative, especially inside a word.
Short pieces are stronger. A few punctuation and chat-format offsets remain.
"""
import math
import re
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
# First seven: Czech/Slovak, Polish, Baltic, and South Slavic.
# The rest are competing Latin-script languages.
LANGUAGES = (
    'cs', 'sk', 'pl', 'lt', 'lv', 'sh', 'sl',
    'en', 'de', 'fr', 'es', 'pt', 'it', 'nl', 'id',
    'tr', 'fi', 'hu', 'ro', 'vi', 'sv', 'da', 'nb',
)
PARTS = regex.compile(r'\p{L}+|[^\p{L}]+')
CYRILLIC = regex.compile(r'\p{Script=Cyrillic}')
LATIN = regex.compile(r'\p{Script=Latin}')

@lru_cache(maxsize=40000)
def word_scores(word):
    return tuple(max(0., zipf_frequency(word, lang) - 1.5)
                 for lang in LANGUAGES)


def language_probs(scores):
    top = max(scores)
    weights = [math.exp(x - top) for x in scores]
    # An undecided language guess must not turn on a rare Slavic response.
    margin = max(scores[:7]) - max(scores[7:])
    confidence = max(0., min(1., (margin - 1.) / 3.))
    for i in range(7):
        weights[i] *= confidence
    total = sum(weights)
    return (sum(weights[:2]) / total, weights[2] / total,
            sum(weights[3:5]) / total, sum(weights[5:7]) / total,
            weights[14] / total)


def advance(carry, text, doc):
    if carry is None or carry[0] != doc:
        carry = (doc, '', (0.,) * len(LANGUAGES), '', 0, '')
    _, word, scores, previous, position, history = carry
    for part in PARTS.findall(text):
        if part[0].isalpha():
            word = (word + part.lower())[-48:]
        else:
            if word:
                if LATIN.search(word):
                    evidence = word_scores(word)
                    scores = tuple(.8 * a + b for a, b in zip(scores, evidence))
                else:
                    scores = tuple(.8 * a for a in scores)
                word = ''
    state = (doc, word, scores, text, position + 1, (history + text)[-120:])
    return state, previous, position




def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    state, previous, position = advance(carry, text, prefix.document_ids[-1])
    token, word = text.strip().lower(), state[1]
    start = text[:1].isspace() or position == 0
    shortness = 1. / (1. + .10 * max(0, len(token) - 3))
    uk = any(c in state[5].lower() for c in 'іїєґ')
    value = 0.

    # Formatting responses, separate from ordinary word pieces.
    tags = {'</think>': .19, '</tool_call>': -.20, '<tool_response>': -.14}
    if text in tags:
        return state, tags[text]
    if text.startswith('<|'):
        return state, 0.
    if previous == '</think>' and text.isspace():
        return state, .20
    if previous == 'Title' and text == ':' and position == 1:
        return state, 3.13
    if '··' in text:
        return state, -.95
    if token == 'się':
        return state, .98

    if CYRILLIC.search(token):
        value -= .034
        ending = re.search('([аиеяыу])ть(ся)?$', token)
        if token == 'ть':
            value += 2.60
        elif ending:
            strength = {'а': 1.81, 'и': 1.48, 'е': 1.92}.get(ending[1], 1.09)
            value += strength * shortness - .29 * bool(ending[2])
        elif token.endswith('ти'):
            value += (.75 + 2.16 * uk) * shortness
        elif token.endswith('т'):
            value += (.57 + .81 * uk) * shortness - .31 * start
            value += .93 * token.endswith('ят') - .12 * token.endswith('ст')
        elif 'т' in token:
            value += (.07 + .19 * bool(re.search('т[ие]', token))) * shortness
        if previous.lower().endswith('т') and not start:
            if token.startswith('ис'):
                value += 1.72
            elif token.startswith(('и', 'і')):
                value += .40 + 1.59 * uk
            elif token.startswith('ь'):
                soft = bool(re.search('[аоиыуеэяюєїі]т$', previous.lower()))
                value += .71 + .53 * soft
            elif token.startswith('ся'):
                value += .70
        if previous == 'ис' and token.startswith('я') and not start:
            value += 1.61

    if 'ت' in token:
        distance = min(4, max(0, word.rfind('ت'))) / 4
        value += -.035 + .38 * start - .43 * token.endswith('ت')
        value -= .26 * distance + .23 * ('تي' in token)
        if token.startswith('ت') and len(token) <= 2:
            value -= .74 * distance

    has_t = bool(re.search('[tť]', token))
    has_c = bool(re.search('[cćč]', token))
    after_t = (previous.lower().endswith(('t', 'ť')) and not start
               and token[:1].isalpha())
    if has_t or has_c or after_t:
        scores = state[2]
        if len(word) >= 3 and LATIN.search(word):
            scores = tuple(a + .5*b for a, b in zip(scores, word_scores(word)))
        cz, pl, baltic, south, indonesian = language_probs(scores)
        if has_t:
            shape = (1. if re.search('[tť]$', token) else .35) * shortness
            if re.search('[aeiouyáéíóúýěů]t$', word):
                shape *= 1.6
            if token.endswith('ct'):
                shape *= 1.8
            if token.endswith('ost'):
                shape *= .3
            if start:
                shape *= .6
            strength = 1.93*cz + .78*pl + 1.67*baltic - .49*south - .09*indonesian
            value += shape * strength
        value += 1.59 * ('ť' in token)
        value += 1.68 * (token.endswith('ć') and not word.endswith('ość'))
        value += .22 * pl * has_c
        value += .21 * (cz + pl + baltic + south) * bool(after_t)
        value += 1.20 * cz * bool(re.search('[áíýů]t$', token))
    return state, float(value)

"""Detect runs of blank formatting and repeated character chunks.

Indented blank lines become strongly negative over successive whitespace
chunks. Horizontal whitespace alone is weaker, especially short indentation.
Repeated symbols (or chunks of one repeated letter) also become negative.
Ordinary text stays near zero; the rarer lexical responses are not modeled.
Only the previous chunk and run lengths are kept; each document resets them.
"""
from math import log1p, log

READS = ()


def repeated_character(text):
    chunk = text.strip()
    if not chunk or '\ufffd' in chunk or len(set(chunk)) != 1:
        return ''
    if len(chunk) == 1 and chunk.isalnum():
        return ''
    return chunk[0]


def width_size(width):
    return min(log1p(width) / log(17), 1.3)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, '', 0)
    _, previous, blanks, old_character, copies = carry
    text = prefix.token_strings[-1]
    whitespace = text.isspace()
    lines = text.count('\n') + text.count('\r')
    width = len(text) - lines
    old_lines = previous.count('\n') + previous.count('\r')
    old_width = len(previous) - old_lines
    size, old_size = width_size(width), width_size(old_width)
    character = repeated_character(text)
    copies = copies + 1 if character and character == old_character else 0
    value = 0.0

    if whitespace and lines and width:
        if blanks == 0:
            value = -0.024 - 0.23 * max(size - 0.25, 0)
            if previous.endswith(('\n', '\r')):
                value -= 0.41
        else:
            # Run length controls onset; widths adjust its strength.
            onset = (0.11, 0.91, 1.56, 1.90)[min(blanks, 4) - 1]
            value = -0.024 - onset - 0.67 * size - 0.40 * old_size
    elif whitespace and lines:
        if blanks == 0:
            value = -0.84 if previous.endswith(('\n', '\r')) else 0.0
        elif blanks == 1:
            value = -0.27 + 0.24 * old_size
        else:
            value = -0.65 - 0.12 * log1p(blanks - 2) + 0.24 * old_size
        value -= 0.05 * min(max(lines - 2, 0), 4)
    elif whitespace and blanks:
        if old_lines and old_width:
            value = -size * (0.21 + 0.75 * (blanks >= 2))
        elif not old_lines:
            value = size * (0.26 - 0.60 * old_size)
            if text == previous:
                value -= 0.23 * size
        value -= 0.125 * size * min(max(blanks - 2, 0), 4)
        value = min(value, 0.0)
    elif copies:
        length = min(log1p(len(text.strip())) / log(5), 1.5)
        value = 0.48 - 0.55 * length - 0.16 * min(copies, 5)
        value -= 0.34 * (text == previous)
        if lines:
            value -= 0.8 * min(copies / 3, 1)
        if character.isalpha():
            value = min(value, -1.3 * length)
        value = min(value, 0.0)
    elif text == previous and text.strip():
        value = -0.15

    state = (doc, text, blanks + 1 if whitespace else 0, character, copies)
    return state, float(value)

programs.haiku:
"""Blank-line runs: the component goes negative inside a stack of empty lines.

Layer-1 MLP down-projection component 2707. Its activation is near zero on ordinary
text and code. It turns negative on whitespace-only lines, the empty lines of a document
or diff (a '+' diff marker before an empty line still counts), and it deepens as the run
of such lines grows: the second blank line gives about -0.9, the third about -2, and from
the fourth to the fourteenth about -2.5 (later, very long runs ease back to about -1.9).
The first blank line after text stays near zero. Two smaller cases: middle-dot and
one-dot leader fill ('··', '․') gives about -1, and a long run of spaces (16 or more, deep
indentation) gives about -0.3.

The program counts consecutive blank-line tokens within a document (the count is the
carry) and resets at each document boundary.
"""

READS = ()

LEADER_FILL = ("··", "․")  # middle dots and one-dot leaders used as filler


def _blank_line(s):
    """Whitespace-only token with a line break, optionally with '+' diff markers."""
    return ("\n" in s or "\r" in s) and s.strip(" \t\r\n\xa0+") == ""


def _value(s, run):
    if _blank_line(s):
        if run == 2:
            return -0.85
        if run == 3:
            return -2.0
        if run >= 15:
            return -1.9
        if run >= 4:
            return -2.5
        return 0.0
    if s in LEADER_FILL:
        return -1.0
    if s.strip(" ") == "" and len(s) >= 16:
        return -0.3
    return 0.0


def step(carry, prefix, upstream):
    run = carry or 0
    if prefix.position > 0 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        run = 0
    s = prefix.token_strings[-1]
    run = run + 1 if _blank_line(s) else 0
    return run, float(_value(s, run))

programs.sol:
"""Sparse text features, not a general model of this component.

Respond positively at web URL scheme separators and quoted test names.
Other rules recognize French/Scandinavian negation, Romance possessives,
"let me", and some punctuation/encoding patterns. An isolated nasal-a
and 3 after an HTML-reference or hexadecimal-escape prefix are negative.
Unrecognized tokens get zero. Only a short within-document history is kept.
"""
import re

READS = ()
TEST_NAMES = {'it', 'test', 'describe', 'context', 'suite', 'specify'}
POSSESSIVES = {'su', 'sus', 'son', 'sa', 'ses'}
FRENCH_POSSESSIVES = {'votre', 'vos', 'leur', 'leurs'}
AUXILIARIES = {'is', 'are', 'was', 'were', 'do', 'does', 'did', 'can',
               'could', 'would', 'should', 'have', 'has', 'had', 'must'}
TEST_LINE = re.compile(
    r'\s*(?:\d+\s+)?(?:it|test|describe|context|suite|specify)\s*'
)
FRENCH_NEGATION = re.compile(r"\bne\b|\bn['’]", re.I)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, recent = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word, before = token.strip(), previous.strip()
    value = 0.0

    if word == '://':
        scheme = before.lower()
        if scheme.endswith('http'):
            value = 1.45 if previous.startswith(' ') else 1.32
        elif scheme.endswith('https'):
            value = 1.00 if previous.startswith(' ') else 0.88
        else:
            value = 0.25
    elif word == '//' and before == ':' and re.search(r'https?\s*:$', recent):
        value = 1.35
