READS = ()

STRONG = {"lip", "lips", "lipid", "lipids"}
WEAK = {"philip", "philips", "slip", "slipped"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].lower().replace(" ", "")
    ctx = "".join(prefix.token_strings[-3:-1]).lower().replace(" ", "")[-2:]
