                return 0.049
            if ending == 'e' and cluster.endswith('rt'):
                return 2.223
            return 0.605 if ending == 'e' else 0.404
        # A doubled consonant across the token boundary is stronger.
        if onset[0] == last and len(onset) == 1:
            return 1.609 if length <= 4 else 0.694
        if last == 'r':
            return 0.383 if length <= 4 else -0.011
        if last in 'lmn':
            return 0.3 if length <= 4 else 0.086
        return 0.141
