    match = re.fullmatch(r'[aeiou]([' + CONSONANTS + r']+)e(s)?', t)
    if match and len(t) <= 5:
        cluster = match[1]
        if cluster in ('nn', 'tt'):
            return 1.443
        if len(cluster) > 1 and len(set(cluster)) == 1:
            return 0.502
        if cluster == 'nt':
            return 0.676
        if cluster == 'rt':
            return 0.345
    return 0.002


