        return 39.11
    if s == '··':
        return 22.32
    if s == '·':
        return 9.05
    if len(s) >= 4 and set(s) == {'^'}:
        return 12.04
    if not s:
        if '\xa0' in text:  # nonbreaking spaces, not ASCII indentation
            return 1.8
        if text == ' ':
            return .54
        if '\n' in text:
            return -.94 if text.count('\n') == 1 else .89
        if text == '\r':
            return 8.65
        return -2.2
    if len(s) == 1 and s in '0123456789':
        return DIGITS[int(s)]
    if s.startswith('//'):
        return 9.74 if '\n' in text else 4.78
    if s.startswith('/*'):
        return 5.5 if '\n' in text else 3.4
    if s.startswith(('"""', "'''")):
        return 5.0
    if len(text) == 1 and text.isascii() and text.isalpha():
        return 2.03 if text.isupper() else .52
    lower = s.lower()
    spaced = text.startswith(' ')
    title = s.istitle()
    # Closed grammatical classes, split by whole-word versus spaced forms.
    if lower in {'not', 'no', 'never', 'neither', 'nor', 'cannot'}:
        return -3.53 if spaced else -2.74 if title else -1.05
    if lower in {'if', 'unless', 'whether'}:
        return -2.30 if spaced else -.41 if title else -3.21
    if lower == 'to':  # infinitive/directional marker
        return -3.94 if title and not spaced else -1.59
    if lower in {'one', 'each', 'every', 'any', 'all', 'some', 'both',
                 'many', 'much', 'few', 'more', 'most', 'less', 'least'}:
        return -1.65 if spaced else -.22
    if lower in {'a', 'an', 'the', 'this', 'that', 'these', 'those'}:
        return -.65 if spaced else 1.59 if title else .19
    if lower in {'def', 'function', 'class', 'struct', 'enum', 'interface',
                 'typedef', 'static', 'extern', 'void', 'int', 'float',
                 'double', 'char', 'bool', 'const', 'var', 'let', 'import',
                 'include', 'require', 'use', 'package', 'namespace',
                 'public', 'private', 'protected', 'export', 'return'}:
        return -1.2
    if not any(c.isalnum() for c in s):
        if s[0] in '([{':
            return 1.23
        if s[0] in ')]}':
            return .49
        if s[0] in '\'"`':
            return .95
        if s[0] in ',;:':
            return 1.10
        if s[0] in '.!?':
            return 1.76
        if s[0] in '#_':
            return 2.88
        if s[0] in '+-=*/%':
            return 1.50
        return .85
    if s.isascii() and s.isalpha():
        if len(s) == 1:
            return 1.72 if s.isupper() else .42
        if spaced:
            return -.20
        if title:
            return .76
        return -.07 if s.isupper() else .87
    return .19


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        first, opening, value = token, True, opening_value(text)
        blank_line, previous = True, ''
    else:
        _, first, opening, value, blank_line, previous = carry
        opening = opening and token == first
    prediction = value if opening else 0.0
    if not opening:
        # List-start 1 versus the 1 and 3 inside multi-digit numbers.
        if text == '1':
            if previous[-1:].isdigit():
                prediction = -.068
            elif blank_line:
                prediction = .145
        elif text == '3' and previous[-1:].isdigit():
            prediction = .041
    if '\n' in text:
        blank_line = not text.rsplit('\n', 1)[-1].strip()
    elif text.strip():
        blank_line = False
    carry = (document, first, opening, value, blank_line, text)
    return carry, prediction

"""Approximate a negative DU/-duce spelling feature, not a general verb feature.

The strongest responses are to produce, reduce, induce and their subword
fragments. Noun and agent endings are usually weaker. The rules also recognize
D + U across tokens, continuations of a word ending in du/duc, and
"of" after -duction.
Latin accents and Cyrillic spellings are transliterated. Case and token
boundaries change the strength. Most other text receives zero, with a small
positive offset at the beginning of a row or document.
"""
from functools import lru_cache
from anyascii import anyascii
import regex
import re

READS = ()

@lru_cache(maxsize=20000)
def spelling(text):
    alphabetic = regex.fullmatch(
        r"[\p{Latin}\p{Cyrillic}\p{Greek}\p{Katakana}\p{Hiragana}"
        r"\p{Common}\p{Inherited}]*", text)
    return anyascii(text).lower() if alphabetic else text.lower()


def response(text, previous, word):
    t, p = spelling(text), spelling(previous)
    spaced = text[:1].isspace()
    # Different endings in the -duc- word family have different strengths.
    families = (("reproduc", -1.8), ("produc", -3.2),
                ("reduc", -1.4), ("induc", -2.1), ("conduc", -1.8),
                ("introduc", -0.4), ("deduc", -1.0), ("seduc", -1.0))
    for root, strength in families:
        if root in t:
            ending = t.split(root, 1)[1]
            if ending.startswith("tion"):
                return -0.8 if root in ("reduc", "deduc") else -0.5
            if ending.startswith("t"):
                return -0.04
            if ending.startswith("er"):
                return -0.2
            if root == "produc":
                if ending.startswith("ed"):
                    strength = -1.9
                elif ending.startswith("ing"):
                    strength = -2.2
                elif ending.startswith("es"):
                    strength = -2.8
            if root == "reduc" and ending == "e":
                strength = -1.25
            return strength * (1.5 if t[:1].isalpha() and not spaced else 1)
    if "ducible" in t:
        return -2.8
    if "du" in t:
        if t.endswith("-du"):
            return -1.7
        if t.strip() == "duc":
            return -3.5 if spaced else -4.5
        if t.strip() == "du":
            if regex.fullmatch(r"\p{Latin}+", text.strip()) and (
                    text.strip().lower() != "du"):
                return -1.0
            if text.strip().isupper():
                return -0.7 if spaced else -7.0
            if text.strip()[0].isupper():
                return -2.4
            return -0.55 if spaced else -3.2
        if "duck" in t:
            return -2.1
        if t.strip() == "duct":
            return -1.1 if spaced else -0.2
        if not spaced and t.startswith("duc"):
            return -3.0 if len(t) <= 4 else -1.8
        if t.endswith("reprodu"):
            return -1.7
        if t.endswith(("produ", "condu")):
            return -3.0
        if t.endswith("introdu"):
            return -0.4
        if t.endswith("redu"):
            return -1.2
        if t.isalpha() and t.endswith("du") and len(t) <= 4:
            return -3.0
        if t.strip().startswith("dup"):
            return -0.3 if spaced else -1.1
        if not spaced and t.startswith("du") and len(t) <= 4:
            return -1.3
        return -0.03
    if t.startswith("u") and p.endswith("d"):
        if t == "u" and text not in ("u", "U") and regex.fullmatch(
                r"\p{Latin}+", text):
            return -1.1
        if t.startswith("urre"):
            return -7.0
        if t in ("uc", "uct", "ux", "uk"):
            return -5.5
        if t.startswith(("ucing", "uce", "uction", "uctive")):
            return -2.4
        if t in ("u", "us", "uo", "up") or t.startswith(("uos", "user")):
            return -3.2
        if t.startswith("uch"):
            return -4.0
        return -0.65
    if not spaced:
        if word.endswith("duc") and t.startswith(("ib", "ial")):
            return -2.7
        if p.endswith("du"):
            if p.endswith("introdu") and t.startswith("cer"):
                return -0.65
            if t in ("c", "z", "j", "k"):
                return -6.5
            return -3.8 if t.startswith(("c", "z", "k", "j")) else -1.5
        if p.endswith("duc") and t.startswith("ing"):
            return -2.0
        if p.endswith("d") and t.startswith("ou") and not t.startswith("ough"):
            return -1.2
        if p.endswith("do") and t.startswith("ku"):
            return -2.0
    if t == " of" and p.endswith("duction"):
        return -2.4 if "induc" in p else -1.6
    return 0.0


def step(carry, prefix, upstream):
    text, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, word = ("", "") if first else carry[1:]
    value = response(text, previous, word)
    if first and value >= -0.3:
        value += 0.18 if text.strip().isdigit() else (
            0.5 if text.startswith("<|") else
            0.55 if text[:1].isalpha() else 0.3)
    tail = re.search(r"[a-z]+$", (word + spelling(text))[-24:])
    return (doc, text, tail[0] if tail else ""), float(value)

"""Approximate an orthographic cor/kor-fragment detector, not word meaning.

Split c/k + vowel + r spellings get the strongest response. Longer endings
and roots embedded in frequent English words are weakened. Code separators,
short endings, capitalization and the core-like noun Corps adjust the response.
A trailing word suffix carries incomplete spellings across token boundaries;
Cyrillic is transliterated. Bare or and some non-r continuations of k
receive small negative values; unrelated activations are left at zero.
"""
import re
import math
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
STRENGTH = {
    'other': 0.05,
    'cor': 3.49,
    'split_other': 0.87,
    'trace_cor': 1.64,
    'split_kor': 7.44,
    'kor': 7.3,
    'rounded_cor': 0.76,
    'divergent_k': -0.96,
    'bare_or': -0.23,
    'split_cor': 7.93,
    'code_cor': 6.17,
    'split_cour': 4.72,
    'split_ko': 6.71,
}

@lru_cache(maxsize=65536)
def spelling(text):
    if re.search('[\u0400-\u052f]', text):
        text = anyascii(text)
    # Keep umlaut vowels distinct from ordinary o and u.
    text = text.replace('ö', 'oe').replace('Ö', 'Oe')
    text = text.replace('ü', 'ue').replace('Ü', 'Ue')
    text = text.replace('œ', 'oe').replace('Œ', 'Oe')
    return ''.join(c for c in unicodedata.normalize('NFKD', text)
                   if not unicodedata.combining(c))

@lru_cache(maxsize=65536)
def frequency(text):
    return zipf_frequency(text, 'en')


def spelling_feature(previous_token, word, original):
    text, word = original.lower(), word.lower()
    previous = previous_token.lower()
    # First look for the entire syllable within the newest token.
    match = re.search(r'([ck])(oeu|oo|ou|oe|ue|[ouia])r', text)
    if match:
        family = ('cor' if match[0] == 'cor' else
                  'kor' if match[0] == 'kor' else
                  'rounded_cor' if match[2] in ('ou', 'oe', 'oeu', 'oo')
                  else 'other')
        tail = text[match.end():].strip()
        head = text[:match.start()].strip()
        scale = (1.0, 0.55, 0.35)[min(len(tail), 2)]
        if len(tail) >= 3:
            scale = 0.04 + 0.25 * math.exp(-0.45 * (len(tail)-3))
        if tail in ('s', 'd', 'ps', 'es'):
            scale = 0.85
        letters = ''.join(c for c in text.strip() if c.isalpha())
        if family == 'cor' and head in ('/', '.', '-'):
            family = 'code_cor'
        elif head:
            if head == 's' and tail == 'ing':
                scale = 0.5
            elif head == 's' and not tail:
                pass
            elif head.endswith(('ac', 're')) and tail:
                scale *= 0.05
            elif len(head) > 4:
                scale *= 0.03
            elif head.endswith('con') and tail:
                scale *= 0.3
            elif frequency(letters) >= 4.5:
                scale *= 0.12
            elif tail:
                scale *= 1.6 if text.endswith(('core', 'cord')) else 0.2
            else:
                scale *= 0.1 if head == 'o' else 0.7
        case = original[match.start():match.end()]
        if case.isupper():
            scale *= 1.4
        # Capitalized Corps, the military noun, is a strong core-like form.
        if tail == 'ps' and case.istitle():
            scale *= 2.5
        if head == 's' and family == 'kor':
            scale *= 0.55
        return family, scale
    # Otherwise complete a syllable begun in earlier tokens.
    if text[:1].isalpha():
        if (original[:1].isupper() and not original.isupper()
                and len(word) > 1 and previous[-1:].islower()):
            return 'other', 0.0
        if word.endswith(('c', 'k')):
            match = re.match(r'(oeu|oo|ou|oe|ue|[ouia])r', text)
            if match:
                vowel = match[1]
                if vowel == 'o':
                    family = 'split_cor' if word.endswith('c') else 'split_kor'
                else:
                    family = 'split_cour' if vowel == 'ou' else 'split_other'
                tail = len(text)-match.end()
                scale = (1.0, 0.7, 0.5, 0.2)[min(tail,3)]
                if tail >= 4:
                    scale = 0.03 * math.exp(-0.5*(tail-4))
                if vowel in ('a', 'i'):
                    scale *= 0.3
                return family, scale
            if (word.endswith('k') and len(text) <= 4
                    and re.match(r'(?:u[nbp]|o(?:ss|ck))', text)):
                return 'divergent_k', 1.0
        if re.search('[ck]o$', word) and text.startswith(('r', 'er', 'eur')):
            return 'split_ko', math.exp(-0.6 * max(0, len(text)-2))
        # A just-completed cor fragment can leave a short continuation trace.
        if re.search('[ck]or$', word):
            scale = math.exp(-0.7 * max(0,len(text)-2))
            if not previous.endswith('cor'):
                scale *= 2.2
            if len(text) == 1 and original.isupper():
                scale *= 2.5
            if word[-3:] == 'kor':
                scale *= 0.2
            if text == 'ps':
                scale = 3.0
            return 'trace_cor', scale
    if text == 'or':
        return 'bare_or', 1.5 if original.isupper() else 1.0
    return 'other', 0.0


def word_tail(word, text):
    match = re.search('[a-zA-Z]+$', word + text)
    return match[0][-32:] if match else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, word = carry[1:] if carry and carry[0] == doc else ('', '')
    text = spelling(prefix.token_strings[-1])
    family, scale = spelling_feature(previous, word, text)
    value = STRENGTH[family] * scale
    return (doc, text, word_tail(word, text)), float(value)

"""Pulses at English auxiliary phrases, especially the prospective 'going to'.

'Going to' is strongest with a nearby form of 'be', weaker as an isolated
phrase, and almost absent after a preposition (a gerund rather than a future).
'Gonna' and present-tense Spanish 'ir a' give similar pulses. Smaller rules
cover semi-modals, contracted perfects, and auxiliary + negative/adverb phrases.
A separate pulse marks the colon in a document-opening 'Title:' header.
Only a short text tail is retained, and documents reset it.
"""
import re

READS = ()
WORDS = re.compile(r"[a-z]+(?:'[a-z]+)?|'[a-z]+|[0-9]+")
BE = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
      "i'm", "you're", "we're", "they're", "he's", "she's", "it's",
      "that's", "there's", "what's", "who's", "isn't", "aren't", "wasn't"}
PERFECT = {'have', 'has', 'had'}
MODALS = {'will', 'would', 'can', 'could', 'may', 'might', 'must', 'shall'}
SPANISH_GO = {'voy', 'vas', 'va', 'vamos', 'vais', 'van'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1].lower().replace('’', "'")
    word = token.strip()
    value = 0.0
    if word == ':' and (text.strip() == 'title' or
                        text.endswith('<|endoftext|>title')):
        value = -10.6
    if word in {'to', 'a', 'gonna', 'gotta', 'be', 'have', 'got', 'been',
                'never', 'ever', 'know', 'supposed', 'gone', 'even'}:
        words = WORDS.findall(text)[-5:] if text.rstrip()[-1:].isalnum() else []
        previous = words[-1] if words else ''
        before = words[-2] if len(words) > 1 else ''
        contracted = previous.endswith(("'ve", "'s"))
        negative = previous.endswith("n't") or previous in {'not', 'never', 'dont'}
        if word == 'to':
            if previous == 'going':
                if before in {'is', "it's", "he's", "she's", "that's",
                              "there's", "what's", "who's"}:
                    value = -10.5
                elif before in {'am', "i'm"}:
                    value = -9.8
                elif before in {'by', 'from', 'to', 'of', 'without', 'for'}:
                    value = -0.3
                elif any(w in BE for w in words[:-1]):
                    value = -8.9
                elif before in MODALS:
                    value = -6.4
                else:
                    value = -3.8
            elif previous == 'about':
                value = -4.9
            elif previous in {'inclined', 'liable', 'unlikely'}:
                value = -2.4
            elif previous == 'likely':
                value = -3.3 if before in BE or before == 'also' else -0.6
            elif previous in {'supposed', 'ought', 'bound', 'guaranteed'}:
                value = -1.3
            elif previous == 'got':
                value = -1.8 if before.endswith(("'s", "'ve")) else -0.3
            elif previous in PERFECT:
                value = -0.35
            elif previous in {'willing', 'owing'}:
                value = -0.65
        elif word == 'a' and previous in SPANISH_GO:
            value = -7.5
        elif word == 'gonna':
            value = -10.3
        elif word == 'gotta':
            value = -2.9
        elif word in {'be', 'have'}:
            if previous == 'to' and before == 'going':
                value = -3.4 if word == 'be' else -2.7
            elif word == 'be' and previous == 'gonna':
                value = -1.8
        elif word == 'got':
            if contracted or (previous == 'really' and before in PERFECT):
                value = -3.8
            elif previous in PERFECT:
                value = -1.5
            elif previous in {'also', 'just', 'still'}:
                value = -0.6
        elif word in {'never', 'ever'}:
            if previous.endswith("'ll"):
                value = -3.0
            elif previous.endswith(("'ve", "'d")):
                value = -2.4
            elif previous in {'have', 'has', 'will', 'would'} or contracted:
                value = -1.7 if word == 'never' else -2.3
            elif previous in MODALS or previous in BE or previous == 'had':
                value = -0.6
            elif negative and word == 'ever':
                value = -1.8
        elif word == 'know' and negative:
            value = -2.3 if previous in {"don't", 'dont'} else -1.0
        elif word == 'been':
            if previous.endswith("'s") or previous == 'its':
                value = -1.25
            elif previous == 'always':
                value = -2.5 if before.endswith("'s") else -0.5
            elif previous == 'never':
                value = -0.5
        elif word == 'supposed' and previous in BE:
            value = -1.0
        elif word == 'gone':
            value = -1.7 if previous.endswith("'s") else -0.7
        elif word == 'even' and negative:
            value = -0.4
    return (doc, (text + token)[-100:]), value

