"""layers.1.mlp.down_proj:2725 -- a "verb is coming" cue for future / intention / necessity.

The component goes strongly negative on the word that sets up a bare verb in a
future, intention, obligation or likelihood construction, and is near zero everywhere
else. Main cases:
  * "going to" / "gonna": the "to" (or "gonna") right before the verb. Strongest, about -9.
  * Spanish "ir a" future: "vamos a", "va a", "voy a": the "a" before the verb, about -8.
  * "be"/"have" right after "going to" ("is going to be"): about -3.4.
  * "got" after have/'ve/'s ("I've got to", "it's got"): about -3.7.
  * "ever", "never", "gone", "know" right after an auxiliary ("will never", "have ever",
    "don't know"): about -1.8.
  * "to" after likely, about, bound, liable, supposed, owing ("likely to", "about to"): about -1.8.

Everything else predicts 0. The values are the mean activations of each case on
training text. The program reads only the current token and up to two tokens before
it, and resets at document boundaries.
"""

READS = ()

SPANISH_GO = {"vamos", "vas", "va", "voy", "vais", "van"}
HAVE = {"have", "has", "'ve", "’ve", "ve", "'s", "’s"}
AUX = HAVE | {"'ll", "’ll", "will", "would", "'d", "’d", "'t", "’t", "dont"}
UNSURE_TO = {"likely", "about", "bound", "liable", "supposed", "owing"}


def step(carry, prefix, upstream):
    s = [x.strip().lower() for x in prefix.token_strings]
    n = len(s)
    cur = s[-1]
    prev = s[-2] if n > 1 else ""
    prev2 = s[-3] if n > 2 else ""
    if n > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    if cur == "gonna" or (cur == "to" and prev == "going"):
        return carry, -9.0
    if cur == "a" and prev in SPANISH_GO:
        return carry, -8.0
    if cur in ("be", "have") and prev == "to" and prev2 == "going":
        return carry, -3.4
    if cur == "got" and prev in HAVE:
        return carry, -3.7
    if cur in ("ever", "never", "gone", "know") and prev in AUX:
        return carry, -1.8
    if cur == "to" and prev in UNSURE_TO:
        return carry, -1.8
    return carry, 0.0

