"""Possessive endings and signed/operator punctuation.

Treat apostrophe-s as possessive, except after contraction subjects like 'it'.
A bare apostrophe is active after plural -s, unless closing a quotation.
Minus is strongest where a signed value can begin, and in shell flags;
ordinary subtraction, hyphens and list markers are much weaker. Other
arithmetic operators get smaller, context-dependent positive values.
Spaced decimal points and doubled interpuncts have fixed small responses.
Keep only 100 preceding characters, resetting at document boundaries.
"""
import re

READS = ()
CONTRACTION_SUBJECTS = set(
    'it he she that there here what who where how when why let this'.split()
)
SHELL_COMMANDS = set(
    'python python3 pip pip3 pytest git grep egrep fgrep sed awk cat head '
    'tail find ls go cargo rustc gcc g++ make cmake curl wget bash sh rm cp '
    'mv mkdir npm npx node java javac docker tar unzip chmod chown sort '
    'uniq wc diff patch xargs echo env test log status show checkout commit push '
    'pull fetch stash reset branch config clone rg gofmt du df ps tee touch '
    'printf'.split()
)
QUANTITY_INTRODUCERS = set(
    'is was be being are were return returns returned yield yields '
    'equal equals to of by about approximately value between from and or '
    'than gives'.split()
)


def predict(s, left, prev):
    t = s.strip()
    tail = left.rstrip()
    c = tail[-1:]
    match = re.search(r'([a-zA-Z]+)$', tail)
    word = match[1] if match else ''
    quoted = bool(re.search(r"(?:[\s(\[=,:])['‘][^'’\n]{0,60}$", left))
    code = any(mark in left for mark in ('_', ';', '&&', '\t', 'return ', '->'))
    code = code or bool(re.search(r'\n {4,}\S', left))

    if t.lower() in {"'s", '’s'}:
        if word.lower() in CONTRACTION_SUBJECTS:
            return -0.01
        if c.isdigit():
            return 0.85
        if len(word) <= 1:
            return 0.29
        return 0.86 if word[0].isupper() else 1.18
    if t in {"'", '’'}:
        plural = len(word) > 3 and c.lower() == 's'
        if not s[:1].isspace() and not quoted and plural:
            return 1.5 if word[0].isupper() else 1.9
        return 0.02
