    toks = prefix.token_strings
    t = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    word = prev.strip()

    # 1. possessive markers
    if t in ("'s", "’s"):
        if word.lower() in CONTRACTION_HOSTS:
            return carry, 0.0
        return carry, 0.9 if word[:1].isupper() else 1.2
    if t == ";s":
        return carry, 1.2
    if t in ("'", "’") and word[-1:] == "s" and word.isalpha():
        return carry, 1.2

    # 2. a minus that opens a value or a flag
    if t == " --":
        return carry, 0.9
    if t in ("=-", ",-"):
        return carry, 1.0
    if t in MINUS_TOKENS:
        if word == "":
            return carry, 0.3
        if word[-1] in OPENERS:
            return carry, 1.5
        if word.isalpha() and len(word) > 1:
            if word in OPERAND_WORDS:
                return carry, 1.4
            if word in SHELL_COMMANDS:
                return carry, 1.1
        return carry, 0.0
    return carry, 0.0

