"""Coordinated possessive references, especially 'and/or its, his, their'.

In English, preceding punctuation and recent possessive words attenuate the
large response. Quantifiers, capitalized conjunctions and subject pronouns also
modify it. Other pronouns and relational modifiers give weaker responses. A few
multilingual equivalents and document-initial 'Title:' labels are included.
All other tokens receive zero; this does not attempt semantic coreference.
"""
import math
import re

READS = ()
# Baseline and additional conjunction response, by third-person possessive.
POSSESSIVES = {
    'her': (-0.04, 4.1),
    'his': (0.0, 7.3),
    'its': (0.19, 9.5),
    'their': (-0.06, 10.5),
}
POSSESSION_CUES = set(POSSESSIVES) | {'my', 'your', 'our'}
RELATIONAL_MODIFIERS = {'similar', 'related', 'corresponding'}


def response(word, history):
    tail = ''.join(history[-4:])
    suffix = r'( (all|(?:any|some) of))?'
    conjunction = re.search(r'(?<!\w)(and|or)' + suffix + '$', tail, re.I)
    punctuated = bool(re.search(r'[,;:—–]\s*(and|or)' + suffix + '$',
                                 tail, re.I))
    if word in POSSESSIVES:
        baseline, strength = POSSESSIVES[word]
        if conjunction:
            exposure = sum(
                math.exp(-distance / 16)
                for distance, token in enumerate(reversed(history))
                if token.strip().lower() in POSSESSION_CUES
            )
            strength /= 1 + 1.5 * exposure
            if conjunction[2]:
                strength *= 0.35 if conjunction[2].endswith('of') else 0.6
            if punctuated:
                strength *= 0.4
            if conjunction[1][0].isupper():
                strength *= 0.4
            if re.search(r'\b(he|she|it|they|him|her|them)\s+(and|or)$',
                         tail, re.I):
                strength *= 0.75
            baseline += strength
        if re.search(r'\b(by|with)$', tail, re.I):
            baseline += 0.31
        if tail.rstrip().endswith(','):
            baseline += 0.77
        if not conjunction and re.search(r'\b(and|or)\W+\w+$', tail, re.I):
            baseline += 0.31
        return baseline
    if conjunction:
        if word in {'it', 'you', 'your', 'our'}:
            weak = {'it': 0.65, 'you': 0.1, 'your': 0.85, 'our': 0.25}[word]
            return weak * (0.3 if punctuated else 1.0)
        if word in RELATIONAL_MODIFIERS:
            return 0.7 if conjunction[1].lower() == 'or' else 2.5
    if word in {"'s", '’s'} and re.search(r'\b(and|or) it$', tail, re.I):
        return 1.2
