    if word in {'его', 'ее', 'её', 'их'}:
        return 7.0 if re.search(r'(?<!\w)(и|или)$', tail) else (
            2.0 if tail.endswith(',') else 0.3)
    if word in {'deren', 'dessen'}:
        return 3.5 if re.search(r'(?<!\w)(und|oder)$', tail) else 0.3
    if word in {'sus', 'su'}:
        return (5.4 if word == 'sus' else 1.7) if re.search(
            r'(?<!\w)(y|o)$', tail) else 0.0
    if word in {'seus', 'suas', 'seu', 'sua'}:
        return 6.6 if re.search(r'(?<!\w)(e|ou)$', tail) else 0.0
    if word == '及其':
        return 10.0
    if word == '及':
        return 0.9
    if word == '其':
        return 0.7
    if word in {'它的', '他的', '她的', '他们的', '它们的'}:
        return 6.0 if tail.endswith(('和', '与', '與', '及')) else 0.3
    if word == ':' and history == ['Title']:
        return 8.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = [] if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(token.strip().lower(), history)
    history.append(token)
    if len(history) > 80:
