"""Component layers.1.mlp.down_proj:2730, as a small token-level rule.

Its activation is near zero on almost all text. It is a sparse, signed detector for a few
kinds of token:
  * +1 on a doubled backslash token (two backslash characters, "\\\\"), the escape for a
    literal backslash inside code strings such as console.log('\\\\nTest') or regex
    patterns;
  * +1 on "www" (as in http://www.example.org);
  * +1 on "@" directly after a word (an e-mail address such as name@host);
  * -1 on a space followed by a doubled backslash (" \\\\"), the LaTeX row break
    in matrices such as "1 & 0 \\\\ 0 & 1".
Everything else predicts 0.
"""

READS = ()

BS = "\\"
ESCAPED_BACKSLASH = {BS * 2, BS * 4}
LATEX_ROW_BREAK = {" " + BS * 2, " " + BS * 2 + "\n"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if tok in ESCAPED_BACKSLASH or tok == "www" or (tok == "@" and prev[-1:].isalnum()):
        value = 1.0
    elif tok in LATEX_ROW_BREAK:
        value = -1.0
    else:
        value = 0.0
    return carry, value

