SUFFIXES = {
    'Inc': -2.6, 'Incorporated': -1.7, 'INC': -1.3, 'LLC': -1.3,
    'Ltd': -7.8, 'LTD': -3.5, 'Jr': -5.6, 'Sr': -3.0,
