    'und': -2.6, 'oder': -2.4, 'sowie': -3.8, 'bzw': -4.5,
    'és': -1.95, 'vagy': -6.0, 'hogy': -1.1,
    'и': -2.0, 'или': -3.5, 'і': -2.0, 'veya': -4.5,
    'et': -0.53, 'ou': -0.6, 'e': -0.3, 'y': -0.18,
    'og': -0.8, 'and': -0.06, 'etc': -1.75,
    '以及': -0.8, '甚至': -1.3, '这样': -0.6,
    '或': -1.15, '等': -1.45, '等等': -3.1,
