        value -= 0.062 * previous.lower().endswith('n')
        value -= (0.058 + 0.128 * prominent) * rarity(previous + token)

    if 'ن' in text and len(text) <= 3:
        if text == 'ن':
            if recent.endswith('آ'):
                value += 0.424
            elif recent.endswith('د'):
                value -= 1.995
            elif recent.endswith('ش'):
                value -= 2.113
            elif token.startswith(' '):
                value -= 0.434
            else:
                value -= 0.573
        elif (any(c in 'پچژگکی' for c in recent)
              and not any(c in 'ایي' for c in text)):
            value -= 3.375 if text.endswith('دن') else 0.340

    if token == ':' and recent == 'Title':
        value += 4.222
    if text and set(text) == {'·'} and recent.endswith('··'):
        value -= 0.435

    recent = (recent + token)[-200:]
    match = re.search('[A-Za-z]+$', previous + token)
    previous = match[0][-40:] if match else ''
    return (doc, previous, recent), float(value)

programs.haiku:
"""Layer-1 MLP down-projection, component 2734: a sparse "word-ending n" feature.

Plain-terms summary. The component is almost always silent (about 0.04% of tokens
fire). It responds to three things, and otherwise predicts 0:

1. The first token of each document. It has a fixed offset that depends on what
   kind of token it is: a word (negative), a digit (slightly negative), punctuation
   (slightly positive).
2. A syllable ending in the letter "n" inside Vietnamese text. Vietnamese-only letters
   (ạ ấ ệ ọ ộ ụ ư ơ ă đ ...) count as Vietnamese; "Vietnamese text" means that at least
   30% of the previous 32 tokens in the same document contain such letters. In that
   context a Vietnamese syllable such as "ần", "dân", "toàn", "phần" pushes it up
   strongly (+0.6), and a plain-Latin-letter "n" syllable such as "con", "can" pushes
   it up more (+1.1).
3. A word-internal fragment, one attached to the previous text with no leading space:
   - a Persian/Arabic-script word ending in the letter ن (noon) pushes it down
     (-0.25; the bare letter ن itself, -0.9);
   - outside Vietnamese text, a Latin-letter name fragment ending in "-ana" pushes it
     down (-0.46), and fragments ending in "-an" or "-na" a little (-0.08; bare "an",
     -0.12). These are the syllables of names like Sunan, Narayan, Mazandaran.

Predictions are the conditional means of these groups, rounded. They explain about a
tenth of the variance; most of the rest is small, token-specific noise.
"""

READS = ()

VIETNAMESE_LETTERS = set(
    "ạảấầẩẫậắằẳẵặẹẻẽếềểễệỉịọỏốồổỗộớờởỡợụủứừửữựỳỵỷỹđăơưĂƠƯĐ"
)
VIETNAMESE_CONTEXT = 0.3  # share of recent same-document tokens with Vietnamese letters
CONTEXT_TOKENS = 32


def _has_vietnamese(text):
    return any(char in VIETNAMESE_LETTERS for char in text)


def _is_latin_word(text):
    return text.isalpha() and text.isascii()


def _is_arabic_script(text):
    return any("؀" <= char <= "ۿ" for char in text)


def _first_token_value(token):
    """Activation at the first token of a document, by kind of token."""
    text = token.strip()
    if not text:
        return -0.02
    if text.isdigit():
        return -0.16
    if text.isalpha():
        return -0.30 if token[:1] == " " else -0.44
    if not any(char.isalnum() for char in text):
        return 0.08
    return -0.24


def _vietnamese_share(prefix):
    """Share of the previous tokens (same document, up to 32 back) with Vietnamese letters."""
    docs = prefix.document_ids
    now = prefix.position
    recent = [k for k in range(max(0, now - CONTEXT_TOKENS), now) if docs[k] == docs[now]]
    if not recent:
        return 0.0
    hits = sum(_has_vietnamese(prefix.token_strings[k]) for k in recent)
    return hits / len(recent)


def step(carry, prefix, upstream):
    now = prefix.position
    token = prefix.token_strings[now]
    docs = prefix.document_ids
    if now == 0 or docs[now] != docs[now - 1]:
        return carry, _first_token_value(token)

    text = token.strip()
    leading_space = token[:1] == " "
    in_vietnamese = _vietnamese_share(prefix) >= VIETNAMESE_CONTEXT

    if in_vietnamese and text.endswith("n"):
        if _has_vietnamese(text):
            return carry, 0.6
        if _is_latin_word(text):
            return carry, 1.1

    if _is_arabic_script(text) and text.endswith("ن") and not leading_space:
        return carry, -0.9 if text == "ن" else -0.25

    if _is_latin_word(text) and not leading_space and not in_vietnamese:
        word = text.lower()
        if word == "an":
            return carry, -0.12
        if word.endswith("ana"):
            return carry, -0.46
        if word.endswith(("an", "na")):
            return carry, -0.08

    return carry, 0.0

"""Null-check detector v4: group magnitudes by operator and null word."""
READS = ()
LOWER_NULLS = {"nil", "null", "None", "nullptr"}
UPPER_NULLS = {"NULL", "undefined"}
EQ_OPS = {"==", "!=", "===", "!=="}

def step(carry, prefix, upstream):
    toks = [s.strip() for s in prefix.token_strings[-3:]]
    cur = toks[-1]
    if len(toks) < 2:
        return carry, 0.0
    prev = toks[-2]
    prev2 = toks[-3] if len(toks) == 3 else ""
    if cur in LOWER_NULLS | UPPER_NULLS:
        if prev in EQ_OPS:
            if cur in UPPER_NULLS:
                return carry, 6.5
            return carry, 13.0 if prev in ("!=", "!==") else 11.0
        if prev == "is" or (prev == "not" and prev2 == "is"):
            return carry, 5.0
        if prev == "return":
            return carry, 2.5
    return carry, 0.0

programs.sol:
"""A source-word detector, strongest for Slavic 'от', 'od', and 'від'.

It recognizes a source prefix even when split across tokens. Longer fused
fragments and the next continuation have weaker responses. Latin 'od' needs
Slavic-language context to distinguish it from English words such as 'odor'.
Fixed phrases ('far from', Russian 'depends on') reduce the source response.
Most responses are negative; unrecognized tokens get zero. State resets for
each document. Line-initial Python "from" gets a small positive value, and
there is a separate response to the tool-output heading OBSERVATION.
"""
import re
from wordfreq import zipf_frequency

READS = ()
LETTERS = re.compile(r'[^\W\d_]+', re.UNICODE)
SOURCE = {
    'von': -.50, 'van': -.40, 'من': -.76, 'từ': -.60,
    '从': -.55, '從': -.55, 'од': -2.2, 'off': -.22,
}
DEPENDENCE = re.compile(r'(?<!не)завис(?:ит|ят|еть|имости|ящего|ящих)\b')
WEAK_FROM = {
    'different', 'differs', 'separate', 'choose', 'benefit', 'learn', 'hear',
}
SLAVIC = ('pl', 'cs', 'sk', 'sh', 'sl')
OTHER = ('en', 'de', 'fr', 'es', 'hu', 'tr')


def slavic_context(text):
    words = [w for w in LETTERS.findall(text.lower()) if len(w) > 1][-5:]
    if not words:
        return 0.0
    def score(lang):
        return sum(zipf_frequency(w, lang) for w in words) / len(words)
    difference = max(map(score, SLAVIC)) - max(map(score, OTHER))
    return min(1.0, max(0.0, .2 + difference / .8))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        oldword, tail, previous = '', '', ''
    else:
        _, oldword, tail, previous = carry
    text = prefix.token_strings[-1]
    match = LETTERS.match(text)
    first = match.group() if match else ''
    joined = oldword + first if first else ''
    # The word fragment being completed by this token.
    pieces = LETTERS.findall(text)
    if first and len(pieces) == 1:
        word = joined
    else:
        word = pieces[-1] if pieces else ''
    if not text[-1:].isalpha():
        word = ''
    old = oldword.lower() if first else ''
    fragment, scale = word, 1.0
    # Negative and compound prefixes can precede the source morpheme.
    if first.lower().startswith(('от', 'od')):
        if old in ('не', 'ne', 'nie', 'со'):
            fragment, old = first, ''
        elif old.endswith(('о', 'е')) or old == 'bio':
            fragment, old, scale = first, '', .65
        elif old == 'пред':
            fragment, old, scale = first, '', .28
    low = fragment.lower()
    value = 0.0

    if low.startswith('от') and not old.startswith('от'):
        # Space-bearing tokens differ from fragments beginning at a line boundary.
        strength = 11.6 if text[:1].isspace() else 16.5
        if fragment[:1].isupper():
            strength += 2.0
        if fragment.isupper():
            strength += 3.5
        value = -strength * scale / max(1, len(fragment) - 1)
        if old and old != 'о':
            value *= .1
        if low == 'от' and DEPENDENCE.search(tail[-30:].lower()):
            value = -4.2
        elif low == 'от' and 'отлич' in tail[-30:].lower():
            value = -8.0
    elif low.startswith('від') and len(old) < 3:
        value = -17.0 / (1 + .4 * max(0, len(fragment) - 3))
    elif first and old.endswith('і') and first.lower().startswith('д'):
        value = -4.8
    elif low.startswith(('od', 'ot')) and len(old) < 2:
        confidence = slavic_context(tail)
        strength = 2.0 + 11.5 * confidence
        if low.startswith('ot'):
            strength = 1.5 + 8.5 * confidence
        value = -scale * strength / (1 + .4 * max(0, len(low) - 2))
        if low.startswith('odd') and confidence < .3:
            value = 0.0
    elif first and old in ('от', 'від', 'od'):
        value = -6.0 / len(first) ** 1.3
    elif text.strip().lower() == 'from':
        value = -.74 if text[:1].isspace() else -.62
        if (not text[:1].isspace() and previous.isspace()) or '\n' in text:
            value = .10  # Python's line-initial import keyword.
        p = previous.strip().lower()
        if p in ('away', 'far', 'aside'):
            value = -.10
        elif p in ('come', 'comes', 'coming', 'came'):
            value = -.33
        elif p in WEAK_FROM:
            value = -.30
        if text.strip() == 'From':
            value = -.50
    elif re.fullmatch(r'[^\w]*from', text.strip()):
        value = -.65
    elif text.strip().lower() in SOURCE:
        value = SOURCE[text.strip().lower()]
    elif text == 'BS' and previous == 'O':
        value = -1.3

    return (doc, word, (tail + text)[-180:], text), value

"""A short-phrase break signal, not a general punctuation detector.

Punctuation is strongest after a few word tokens, weaker immediately after
another break or after a long span. Questions, exclamations and ellipses get
larger values. Word shape distinguishes prose from initials, numbers and
compound code punctuation. A few inline linking words also get a positive
value. The first token of each document has a separate negative baseline.
"""
import regex

READS = ()


def break_kind(text):
    mark = text.strip()
    if not mark:
        return 'line' if '\n' in text else None
    if any(c.isalnum() for c in mark):
        return None
    if '…' in mark or '...' in mark:
        return 'ellipsis'
    equivalents = {'，': 'comma_han', '。': 'period', '、': 'comma',
                   '！': 'bang', '？': 'question', '：': 'colon', '；': 'semi'}
    for char in mark:
        if char in equivalents:
            return equivalents[char]
    for char in reversed(mark):
        if char in '.,:;!?':
            return {'.': 'period', ',': 'comma', ':': 'colon',
                    ';': 'semi', '!': 'bang', '?': 'question'}[char]
    return None


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, '', 0)
    _, previous, span = carry
    kind = break_kind(text)
    state = (doc, text, 0 if kind else span + 1)
    word = text.strip()

    if first:
        value = -0.73 if word.isalpha() else (-0.44 if word.isdigit() else -0.32)
    elif kind is None:
        value = -0.003
        if text.startswith(' '):
            if word.lower() in {'but', 'yet'}:
                value = 0.38 if word.islower() else 0.15
            elif word == 'because':
                value = 0.24
            elif word == 'until':
                value = 0.18
            elif word.lower() == 'maybe':
                value = 0.23
    else:
        emphatic = kind in {'bang', 'question', 'ellipsis'}
        prev_word = previous.strip()
        if span > 12:
            value = (0.23 if emphatic else 0.03) if span <= 19 else -0.07
        elif not prev_word.isalpha():
            value = 0.27 if emphatic else 0.03
        elif span <= 2:
            value = 0.37 if text.count('\n') >= 2 else 0.06
        elif emphatic:
            value = 0.50 if kind == 'bang' else 0.70
        elif len(word) > 1:
            value = 0.06
        elif span <= 8:
            if kind == 'comma_han':
                value = 0.72
            elif previous.startswith(' '):
                if prev_word.islower() and len(prev_word) > 1:
                    value = 0.39
                else:
                    value = 0.42 if kind == 'line' else 0.11
            elif regex.search(r'\p{Script=Han}', previous):
                value = 0.43
            else:
                value = 0.14
        else:
            value = 0.05 if prev_word.istitle() else 0.17
    return state, value

programs.haiku:
"""Layer 1, MLP down-projection component 2737: a short-clause boundary detector.

What it responds to: the punctuation and line breaks that close a *short* sentence
or clause, and the conjunction "but" that joins two clauses. The response is:

  * by mark: a question or exclamation mark is strongest; then an ellipsis, a
    full-width comma, a comma/full stop/line break; a semicolon or colon is weakest;
    "but" is moderate;
  * by sentence length: it grows over the first few tokens of a sentence, peaks
    at about 5-9 tokens, and is gone by about 25 tokens. So the commas of a long
    sentence stay quiet, while a short sentence's end is loud;
  * damped when the word before is a number (list items "2.", decimals);
  * boosted when the word before closes a clause ("...it?", "...see.", "...up,");
  * slightly negative on the middle dot "··", a separator.

Only the sentence length needs state: a count of tokens since the last sentence
end, reset at each document start.
"""

READS = ()

END_MARKS = "?!？！‼"
SENTENCE_END = ".?!\n。？！…"
CLOSERS = {"it", "you", "me", "them", "there", "up", "down", "out", "again",
           "now", "see", "that", "this", "here"}


def length_factor(n):
    """n: tokens so far in the current sentence, counting this token."""
    if n <= 1:
        return 0.0
    if n == 2:
        return 0.1
    if n <= 4:
        return 0.5
    if n <= 9:
        return 1.0
    if n <= 12:
        return 0.8
    if n <= 16:
        return 0.45
    if n <= 22:
        return 0.2
    return 0.0


def mark_strength(tok):
    core = tok.strip()
    if core == "":
        return 0.3 if "\n" in tok else 0.0
    if core == "but":
        return 0.6
    if "..." in core or "…" in core:
        return 0.8
    if core == "，":
        return 0.75
    if core in ("。", "、"):
        return 0.45
    if all(c in END_MARKS for c in core):
        return 1.0
    if all(c in ".．" for c in core) or all(c in ",，、" for c in core):
        return 0.3
    if all(c in ";；:：" for c in core):
        return 0.18
    return 0.0


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    n = 1 if new_doc or carry is None else carry + 1  # tokens in this sentence so far
    if "··" in tok:
        value = -1.2
    else:
        value = mark_strength(tok) * length_factor(n)
        if value and not new_doc:
            before = prefix.token_strings[-2].strip()
            if before[-1:].isdigit():
                value *= 0.4
            elif before in CLOSERS:
                value *= 1.6
    next_carry = 0 if any(c in SENTENCE_END for c in tok) else n
    return next_carry, float(value)

programs.sol:
"""A Japanese long-/o/ and /u/ continuation detector, with Thai tone marks.

An isolated u-kana is strongest after an o-vowel kana. Short long-o
kana chunks also fire; longer expressions are weaker or ignored.
A smaller Cyrillic o/u rule uses the same local vowel pattern.
Thai upper-vowel/tone-mark combinations have the opposite sign.
There are separate responses to unfinished Tibetan/Ethiopic characters,
document-initial runs of identical middle-dot/carriage-return tokens,
and selected document-initial comment/markup openers.
"""
import unicodedata
from anyascii import anyascii

READS = ()


# Compare hiragana and katakana through a shared syllabary.
def hiragana(s):
    return ''.join(chr(ord(c) - 96) if 'ァ' <= c <= 'ヶ' else c
                   for c in s)


def kana_vowel(ch):
    # Small tsu marks gemination rather than a vowel.
    if ch and 'ぁ' <= ch <= 'ゖ' and ch != 'っ':
        return anyascii(ch)[-1:]
    return ''


# Strength of a written long-o syllable, grouped by its onset.
LONG_O = {
    'こ': 9.8, 'そ': 9.1, 'も': 8.7,
    'と': 4.5, 'ど': 5.0, 'ろ': 4.6,
    'よ': 4.0, 'ょ': 4.0,
}


def script_fragment(raw, previous):
    """A middle UTF-8 byte can already identify a syllabary or subjoined sign."""
    if (len(raw) == 1 and 128 <= raw[0] < 192 and previous
            and 224 <= previous[-1] < 240):
        # Lowest possible codepoint of this still unfinished character.
        low = ((previous[-1] & 15) << 12) | ((raw[0] & 63) << 6)
        name = unicodedata.name(chr(low), '')
        # Check all 64 possible final bytes, not a guessed future character.
        if name.startswith('TIBETAN') and any(
            unicodedata.name(chr(c), '').startswith('TIBETAN SUBJOINED')
            for c in range(low, low + 64)
        ):
            return -8.5
        if name.startswith('ETHIOPIC SYLLABLE'):
            return -4.4
    return None


def estimate(raw, previous, initial_run=False):
    if raw == '··'.encode():
        return 1.72 if initial_run else 0.0
    if raw == b'\r' and initial_run:
        return 3.47
    if not previous and raw in (b'//\n', b'<!', b'#\n'):
        return 6.8
    if raw.isascii():
        return 0.0
    fragment = script_fragment(raw, previous)
    if fragment is not None:
        return fragment
    original = raw.decode('utf8', 'ignore')
    s = hiragana(original)
    p = hiragana(previous.decode('utf8', 'ignore')[-1:])
    vowel = kana_vowel(p)
    if s == 'う':
        katakana = original == 'ウ'
        if vowel == 'o':
            return 8.5 if katakana else 11.4
        if vowel == 'i':
            return 3.7
        if vowel in ('u', 'e'):
            return 5.5
        if vowel == 'a':
            return 3.4 if katakana else 1.85
        return 0.75 if katakana else 1.35
    if original == 'く':
        return 2.8 if vowel == 'o' else 0.8
    if s.casefold().startswith('у') and p.casefold() == 'о':
        return 5.4 / len(s)
    if s == 'しよう':
        return 5.3
    if s == 'よう':
        # Verb-stem + you (volitional) versus dictionary-form + you (like).
        return 7.5 if vowel in ('i', 'e') else 2.8
    for i in range(len(s)-1):
        if s[i+1] == 'う' and s[i] in LONG_O:
            suffix = s[i+2:]
            if s[:i+1] == 'そ':
                if suffix == 'な':
                    return 6.0
                if suffix in ('だ', 'で'):
                    return 3.4
            if suffix not in ('', 'です'):
                return 0.0
            extra = len(s) - 2
            return LONG_O[s[i]] * 0.58 ** extra
    if s in ('ー', 'ーる'):
        if vowel == 'o':
            return 2.5 if len(s) == 1 else 1.3
        return 0.0
    before = previous.decode('utf8', 'ignore')
    preposed_vowel = len(before) >= 2 and before[-2] in 'เแโใไ'
    if s == '้':
        if p == 'ั' or (p == 'ด' and not preposed_vowel):
            return -4.0
        if p in set('ึุ'):
            return -3.1
        if p in set('ิื'):
            return -1.9
    if s == '้า':
        if p == 'ข':
            return -1.7 if preposed_vowel else -8.5
        return -0.8
    if s in ('ึ', 'ื', '็'):
        return -0.9
    if s == '่ว':
        return -1.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_bytes[-1]
    # Retain whether this document has contained only one repeated token.
    if carry is None or carry[0] != doc:
        previous, repeated = b'', raw
    else:
        previous = carry[1]
        repeated = raw if carry[2] == raw else None
    value = estimate(raw, previous, repeated == raw)
    return (doc, (previous + raw)[-12:], repeated), value

"""Approximate a type-conversion/typed-literal signal in source code.

Predict a strong negative value at the end of a C/Java-style cast, using
primitive types and type-name syntax rather than an identifier table.
Pointer casts and punctuation bundled with an operand get weaker values.
Array literals, C++ casts, and generic constructors get smaller negatives.
Separate positives cover user-header newlines, a document-leading run of
middle dots/whitespace, and "tests" immediately after "__". Otherwise predict
zero. Keep 256 characters of history, reset at document boundaries.
"""
import re

READS = ()
PRIMITIVES = set('bool boolean byte char short int long float double void '
                 'string object decimal sbyte ushort uint ulong wchar_t '
                 'size_t ssize_t intptr_t uintptr_t array str'.split())
TYPE_CHARS = re.compile(r'^[\w\s.$:*&<>?,\[\]]+$')


def cast_type(text):
    """A type has one qualified name, optional modifiers and type suffixes."""
    text = text.strip()
    tagged = text.startswith(('struct ', 'enum ', 'union '))
    if not text or not TYPE_CHARS.fullmatch(text):
        return False
    # Collapse generic arguments, including nested generic types.
    while re.search(r'<[^<>]*>', text):
        text = re.sub(r'<[^<>]*>', '', text)
    text = re.sub(r'\b(?:const|volatile|unsigned|signed|struct|enum|union)\s+',
                  '', text).strip()
    if text.startswith('long '):
        text = text[5:]
    match = re.fullmatch(r'([A-Za-z_$][\w$]*(?:(?:\.|::)[A-Za-z_$][\w$]*)*)'
                         r'(?:\s*(?:\*|&|\[\]|\?))*', text)
    if not match:
        return False
    name = re.split(r'\.|::', match[1])[-1]
    return (tagged or name in PRIMITIVES or name[:1].isupper()
            or name.endswith(('_t', 'ptr', 'Type')))


def cast_ending(token, before):
    if ')' not in token:
        return False
    closing = token.index(')')
    if token[closing+1:closing+2] in (')', ';', ',', '}', ']'):
        return False
    left = before + token[:closing]
    opening = left.rfind('(')
    if opening < 0 or not cast_type(left[opening+1:]):
        return False
    direct = left[opening-1:opening]
    if direct and (direct.isalnum() or direct in '_.$>'):
        return False
    lead = left[:opening].rstrip()
    body = left[opening+1:]
    names = re.findall(r'[A-Za-z_$][A-Za-z_0-9$]*', body)
    if not names or re.search(r'[A-Z]_[a-z0-9]+$', names[0]):
        return False
    if re.search(r'operator\s*=$', lead):
        return False
    if names[0].isupper() and len(names[0]) > 1 and '*' not in body:
        return False
    # Single capital letters are usually math variables, not class names.
    if len(names[0]) == 1 and names[0].isupper():
        if names[0] != 'T' or not re.search(r'[;{}]', lead):
