          "this": 1.4, "that": 1.4, "its": 1.3, "my": 0.7, "his": 0.7, "her": 0.7}

# "to" after a verb of possession, the obligation "have to" (value -6.5 at strength 1.0)
TO_AFTER = {"have": 1.0, "has": 1.15, "had": 0.95, "got": 0.7, "get": 0.45, "gets": 0.45,
            "gotta": 0.6, "going": 0.2, "supposed": 0.15}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if cur == "to":
        return carry, -6.5 * TO_AFTER.get(prev, 0.0)
    if cur in ("'t", "’t") and prev == "can":
        return carry, -1.0
    if cur == "sure" and prev == "not":
        return carry, -0.8
    return carry, VERB.get(prev, 0.0) * OBJECT.get(cur, 0.0)

programs.sol:
"""A lexical detector centered on 干 and the visually similar 千.

Whole-token 干/幹/乾/千 have large negative responses; most longer words
containing them do not. Listed compounds and the 貫/慣 family respond more
weakly. Recent kana lowers several responses in Japanese text. A character
completed by a UTF-8 continuation token responds more strongly. The Korean
syllables 간/천 have weaker, word-dependent responses. Everything else is zero.
This approximates the conspicuous lexical response, not the diffuse background.
"""
import regex

READS = ()
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
THOUSAND_PREFIXES = frozenset('一二两三四五六七八九十百数几上近万')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    t = prefix.position
    if carry is None or carry[0] != doc:
        kana_age = 1000
    else:
        kana_age = carry[1] + 1
    text = prefix.token_strings[-1].strip()
    if KANA.search(text):
        kana_age = 0
    japanese = kana_age <= 24
    previous = ''
    if t and prefix.document_ids[-2] == doc:
        previous = prefix.token_strings[-2]

    # At most three adjacent tokens are needed to finish a three-byte Han char.
    split = False
    if '\ufffd' in text and previous:
        start = max(0, t - 2)
        while prefix.document_ids[start] != doc:
            start += 1
        tail = b''.join(prefix.token_bytes[start:]).decode('utf-8', 'replace')
        if tail and tail[-1] in '干千幹乾':
            text, split = tail[-1], True

    value = 0.0
    if text == '干':
        value = -9.1 if split else (-5.5 if japanese else -6.3)
    elif text == '幹':
        value = -6.8
    elif text == '千':
        value = -7.4 if split else (-4.1 if japanese else -5.0)
        if previous.endswith('秋'):
            value = -8.2  # 秋千 (swing)
    elif text == '乾':
        value = -3.8 if japanese else -4.8
    elif text == '若干':
        value = -4.2 if japanese else -6.5
    elif text in ('相干', '干细胞'):
        value = -3.3
    elif text == '干部':
        value = -0.6
    elif len(text) == 2 and text[1] == '千' and text[0] in THOUSAND_PREFIXES:
        value = -1.8 if text[0] == '一' else -2.8
    elif text in ('貫', '贯', '一贯', '一貫'):
        value = -3.1
    elif text in ('惯', '慣'):
        value = -1.4
    elif text == '천':
        if previous.endswith('추'):  # 추천: recommendation
            value = 0.0
        else:
            value = -3.4 if previous.rstrip()[-1:].isdigit() else -2.0
    elif text == '간':
        if previous.endswith('약'):  # 약간: a little
            value = -3.2
        else:
            value = -0.2 if previous.endswith('공') else -1.2
    return (doc, kana_age), value

"""A sparse approximation using local words and typography.

Positive rules cover continuing nonbreaking-space padding, equal-sign and
middle-dot runs, Tokyo and audio-volume word completions, and length/size
superlatives. Dot leaders and Chinese interrogatives/post-verbal particles
have negative rules. Run lengths and token boundaries affect the magnitude.
Everything else predicts zero. The byte carry only reconstructs characters
across token boundaries and resets at document boundaries.
"""
from functools import lru_cache
import cedict

READS = ()

QUESTION_WORDS = frozenset((
    '什么', '甚麼', '什麼', '啥', '谁', '誰', '哪', '哪里', '哪裡',
    '哪儿', '哪个', '哪個', '怎', '怎么', '怎麼', '为什么', '為什麼', '多少',
))

@lru_cache(maxsize=4096)
def is_verb(word):
    return any(g.startswith('to ') for g in cedict.glosses(word))


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    same_doc = (len(prefix.document_ids) > 1 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    prev = prefix.token_strings[-2] if same_doc else ''
    tail = (carry or b'') if same_doc else b''
    before = tail.decode('utf-8', errors='ignore')
    tail = (tail + prefix.token_bytes[-1])[-24:]
    value = 0.0

    # Nonbreaking-space runs: lengths count characters, not token IDs.
    if '\xa0' in s and not s.strip(' \xa0') and prev.endswith('\xa0'):
        a, b = prev.count('\xa0'), s.count('\xa0')
        if a == 4:
            value = 2.1 if b == 1 else (3.5 if b == 2 else 0.3)
        elif a == 8:
            value = 1.7 if b == 2 else (0.38 if b == 8 else 0.24)
        else:
            value = 0.28 if b == 1 else (-0.14 if b == 2 else 0.2)
    elif s and len(set(s)) == 1 and prev.endswith(s[0]):
        c = s[0]
        if c == '=':
            value = 0.8 if prev == '=' * 16 else 0.45
        elif c == '.':
            value = -3.1 if len(prev.strip()) == 64 else -0.55
        elif c == '·':
            value = 4.5 if len(s) == 1 else 0.86
        elif c == '_':
            value = -0.12
    elif s == ' ·' and prev.endswith('·'):
        value = 2.4
    elif before.endswith('東') and s in ('京', '京都'):
        value = 4.4
    elif before.endswith('音') and s == '量':
        value = 2.5
    elif before.endswith('最') and s in ('大', '小', '长', '長', '短'):
        value = 2.1
    elif s in ('最大', '最小'):
        value = 0.7
    elif s in ('最大的', '最小的'):
        value = 0.2
    elif s.strip().lower() in ('longest', 'shortest'):
        value = 0.3 if s.strip().lower() == 'longest' else 0.65
    elif s in ('是什么', '是什麼', '是多少'):
        value = -1.0
    elif s in QUESTION_WORDS:
        value = -1.7 if prev.endswith('是') else -0.3
    elif s in ('着', '到', '到了') and is_verb(prev):
        if len(prev) > 1:
            value = -0.8 if s == '着' else (-0.45 if s == '到' else -0.3)
        else:
            value = -0.05
    return tail, value

"""A local VE-spelling approximation, not a semantic classifier.

Short Latin ve and Cyrillic ве fragments are positive, including v + e
split over adjacent tokens. Diacritics, case, fragment length and a few
spelling continuations modulate this. Most other text is near zero.
Only the preceding token is remembered; document boundaries reset it.
"""
import unicodedata

READS = ()


def activation(previous, current):
    p, c = previous.lower(), current.lower()
    s = c.lstrip(' _./-')
    first = ''.join(ch for ch in unicodedata.normalize('NFD', c[:1])
                    if unicodedata.category(ch) != 'Mn')
    joined = bool(c and c[0].isalpha())
    value = 0.001

    # Short VE fragments, as opposed to longer words or VER/VENT.
    if s.startswith('ve') and not s.startswith(('ver', 'vent')):
        value += 1.219 / max(1, len(s)-2)
        if len(s) <= 3 and joined:
            if p and p[-1].isalpha():
                value += 0.52
            if p.endswith('e'):
                value += -1.249
    if s.startswith(('ver', 'vent')):
        value += 0.108
    if s.startswith('ве'):
        value += 0.802 / max(1, len(s)-4)

    # A preceding vowel and the extended IVE suffix give weaker responses.
    if s.startswith(('ave', 'ove', 'uve')):
        value += 0.291 / max(1, len(s)-2)
        if joined and p.endswith(('e', 'i')):
            value += -0.113
    if s.startswith('ive') and len(s) > 3:
        value += -0.17
        if joined and p.endswith('h'):
            value += -2.24

    # Reassemble a V-E spelling broken at a token boundary.
    if joined and p.endswith(('v', 'в')):
        if first in ('e', 'е', 'э'):
            strength = 0.825
            if len(p.strip()) == 1:
                strength += 1.288
            if c[:1] in ('е', 'ё', 'э'):
                strength += 0.748
            if current.isupper():
                strength += 1.629
            if p.endswith(('ств', 'stv')):
                strength += -1.38
            value += strength / max(1, len(c)-3)
            if c[:1] in ('ě', 'ё'):
                value += 2.317
        elif first in ('i', 'и', 'u', 'у'):
            value += 0.189
            if p.endswith(('ev', 'ев')):
                value += -0.396

    # Continuing VE as VEILL or VEC/VECK carries some response forward.
    if joined and p.endswith('ve') and len(p.strip()) <= 3:
        if c.startswith(('ill', 'il')):
            value += 3.477
        elif c.startswith(('ck', 'c', 'k')):
            value += 1.937
    if s == 'ベ':  # Katakana BE is another positive syllable.
        value += 1.692
    return float(value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    current = prefix.token_strings[-1]
    return (doc, current), activation(previous, current)

"""A detector for written numerical boundaries, not an arithmetic evaluator.

Give a large negative response to the second separator of dates and times,
and to an equals sign following numeric arithmetic. Smaller responses mark
clock fields and date/time units. Keep a short text suffix, clearing it when
the document changes. Other text is approximately inactive.
"""
import re

READS = ()
NUMBER = r'\d+(?:[.,]\d+)*(?:[eE][-+]?\d+)?'
MONTH = r'(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*'
DAY = r'\d{1,2}(?:st|nd|rd|th)?'
DATE = (r'(?:\d{4}[-/.]\d{1,2}[-/.]\d{1,2}'
        r'|\d{1,2}[-/.]\d{1,2}[-/.]\d{2,4}'
        r'|' + DAY + ' +' + MONTH + r' +\d{4}'
        r'|' + MONTH + ' +' + DAY + r',? +\d{4}'
        r'|\d{4}年\d{1,2}月\d{1,2}日)')
CLOCK = r'\d{1,3}:\d{2}(?::\d{2})?'


def response(before, token):
    # Weak marks at the end of a clock field or a calendar field.
    if token.isdecimal() and len(token) == 1:
        full = before + token
        if re.search(r'\d{1,3}:\d{2}:\d{2}\Z', full):
            return -0.75
        if re.search(r'\d{1,3}:\d{2}\Z', full):
            return -0.23
    if token in (' AM', ' PM') and re.search(CLOCK + r'\Z', before):
        return -3.6
    if token == 'Z' and re.search(CLOCK + r'\Z', before):
        return -1.5
    if token == ' ' and re.search(MONTH + r' +\d{1,2}\Z', before):
        return -1.6

    symbol = token.strip(' ')
    if re.fullmatch(r'\)*[=≈][-+]?', symbol):
        # A token can combine a closing parenthesis, =, and an answer's sign.
        left = before + re.split('[=≈]', symbol)[0]
        left = left.rstrip(' \t').rstrip(')]}').rstrip(' \t')
        left = left.replace(r'\times', '×').replace(r'\cdot', '×')
        left = left.replace(' х ', ' × ').replace(' : ', ' ÷ ')
        left = re.sub(r'(?<=\d)x(?=\d)', '×', left)
        left = left.replace('²', '^2').replace('³', '^3').replace('–', '−')
        if '≈' in symbol and re.search(r'\d\Z', left):
            return -2.1
        calculation = re.search(
            r'(?:' + NUMBER + r'|\))[ \t]*([+*×÷/−-]|\*\*|\^)'
            r'[ \t]*\(?[ \t]*[-−]?' + NUMBER + r'\Z', left)
        if calculation:
            prior = left[:calculation.start()]
            # Do not mistake a variable's exponent for a numeric operand.
            if not prior or not (prior[-1].isalpha() or prior[-1] in '^_'):
                return -1.9 if calculation[1] in ('/', '÷', '^', '**') else -4.7
        return -0.1 if re.search(r'\d\Z', left) else 0.0

    if symbol not in ('-', '/', '.', ':', '月', '日') or token != symbol:
        return 0.0
    number = re.search(r'(\d+)\Z', before)
    if not number:
        return 0.0
    n = number[1]
    preceding = before[:number.start()]
    previous = re.search(r'(\d+)([-/.:年月])\Z', preceding)
    if symbol == ':' and len(n) <= 2:
        if previous and previous[2] == ':' and len(n) == 2:
            return -9.2
        if not preceding or preceding[-1].isspace() or preceding[-1] == 'T':
            if int(n) <= 23:
                if re.search(DATE + r'[^0-9]{0,12}\Z', preceding):
                    return -2.9
                return -1.4 if len(n) == 2 else -0.1
    if previous:
        first, sep = previous.groups()
        if symbol == '.' and sep == ':' and len(n) == 2:
            return -3.4
        if symbol == '月' and sep == '年':
            return -1.2 if len(n) == 2 else -0.4
        if symbol == '日' and sep == '月':
            return -1.2
        if symbol == sep and symbol in '-/.':
            if len(first) == 4 and 1000 <= int(first) <= 2999:
                if len(n) <= 2 and 1 <= int(n) <= 12:
                    if symbol == '.':
                        lead = preceding[:previous.start()]
                        if len(n) != 2 or re.search(r'[A-Za-z0-9_.]\Z', lead):
                            return 0.0
                    return {'-': -13.2, '/': -8.8, '.': -4.4}[symbol]
            if len(n) <= 2:
                if symbol == '-':
                    return -4.5  # Also covers hyphenated numeric identifiers.
                if symbol == '/' and len(first) <= 2:
                    return -5.0
            if symbol == '-' and len(first) == len(n) == 3:
                return -1.6  # Telephone-number grouping.
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-160:]), float(response(before, token))

"""A sparse spelling detector, chiefly for wiki/Wikipedia and short wi- fragments.

Chinese 維/维 and 吾/吴 are a second family of strong triggers.  思維 (thought)
strengthens the first one; 維持 (maintain) extends it to its second character.
There is also a weaker response to 'up' after particular verbs, with
WordNet recognizing their inflected forms.
Everything else is left at zero rather than memorizing small token effects.
"""
import re
import wordnet

READS = ()


def response(token, before):
    s = token.strip().lower()
    split_w = before.lower().endswith('w') and token[:1].lower() == 'i'
    fragment = 'w' + s if split_w else s.lstrip('./_')
    if fragment in ('wik', 'wiki', 'wikip'):
        if s.startswith('/'):
            return 4.4
        return 10.5 if split_w else 8.5
    if fragment == 'wikipedia':
        return 4.6 if split_w else 6.0
    if fragment.startswith('wikimedia'):
        return 2.0
    if fragment == 'wick':
        return 2.6
    if fragment in ('wig', 'wigg'):
        return 1.9 if split_w or token.startswith(' ') else 3.6
    if fragment in ('wil', 'wilk', 'wink'):
        return 1.8
    if fragment == 'wii':
        return 1.6
    if split_w and s in ('i', 'it', 'ich', 'ic', 'ix', 'ini'):
        return 1.3
    if s == 'vik':
        return 2.5
    if fragment in ('wiss', 'wist', 'witter'):
        return -0.8
    if s == '維':
        return 12.5 if before.endswith('思') else 4.7
    if s == '维':
        return 4.8
    if s in ('维持', '思维'):
        return 4.4
    if s == '持' and before.endswith(('维', '維')):
        return 4.8
    if s == '基' and before.endswith(('维', '維')):
        return 10.0
    if s == '吾':
        return 8.4
    if s in ('吴', '吳'):
        return 4.1
    if s.startswith('ики') and before.endswith(('в', 'В')):
        return 7.5
    if s == 'wu':
        return 2.0
    if s == '百科' and before.endswith(('维基', '維基')):
        return 6.0
    if s in ('up', '-up'):
        word = re.search(r'([a-z]+)$', before.lower())
        word = word.group(1) if word else ''
        roots = set(wordnet.base_forms(word)) | {word}
        if roots & {'warm', 'wake'}:
            return 1.8
        if 'keep' in roots:
            return 1.5
        if roots & {'wind', 'tie'}:
            return 1.0
        if 'follow' in roots:
            return 0.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    # Joining bytes preserves characters that span token boundaries.
    before = tail.decode('utf-8', errors='replace')
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (doc, (tail + prefix.token_bytes[-1])[-120:]), value

"""Approximate several rare document-formatting responses.

A document-initial ``Title:`` field has a large, two-stage response.  Other
positive rules mark space/tab switches, padded blank lines, and single
backticks in text containing both backticks and nonbreaking-space indentation
(as in scraped code).  Opening chat blocks have a smaller response.  Ordinary
text stays near zero, with coarse negative offsets at document starts and for
repeated middle dots.  State is reset between documents.
"""
READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        p, recent, position = '', '', 0
    else:
        _, p, recent, previous_position = carry
        position = previous_position + 1
    value = 0.0
    marked_code = '\xa0' in recent and recent.count('`') >= 2
    if len(s) >= 2 and set(s) == {'·'}:
        value = -1.77
    elif not p:
        if s == 'Title':
            value = -2.06
        elif not s.strip():
            value = 0.0
        elif s.isascii() and s.strip().isalpha():
            value = -0.23 if s.startswith(' ') else -0.42
        else:
            value = -0.3
    elif position == 1 and p == 'Title' and s == ':':
        value = 7.3
    elif s in ('`', ' `') and marked_code:
        if p.endswith('`'):
            value = 0.45
        elif p.isspace():
            value = 1.05
        elif p.strip().isalpha():
            value = 1.12
        else:
            value = 1.25
    elif s.startswith('\t'):
        if p.endswith(' '):
            value = 1.25
        elif s.isspace() and ' ' in s:
            spaces = s.count(' ')
            if spaces < 4:
                value = -0.14
            else:
                value = 0.06 if spaces < 12 else 0.27
    elif s and set(s) == {' '} and p.endswith('\t'):
        value = 0.75 if len(s) >= 20 else 0.1
    elif s.startswith('\n') and p.endswith(' '):
        value = 0.8 if len(s) >= 2 else 0.35
    elif s.startswith('\xa0') and p.endswith(' '):
        value = 1.1
    elif s == '\n\n' and p in ('<think>', '<tool_response>'):
        value = 0.18
    return (doc, s, (recent + s)[-256:], position), value
